        [MenuItem("BubuTown/Create Visible Prototype Scene")]
        public static void CreateVisiblePrototypeScene()
        {
            EnsureFolders();
            EnsureMaterials();

            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            scene.name = "BubuTownPrototype";

            var root = new GameObject("BubuTown_Prototype_All_Visible_Before_Play");
            var manifest = root.AddComponent<BubuTownSceneManifest>();
            manifest.ProjectSummary = "《布布的小镇生活》: 3D cozy town-life prototype with quests, coins, furniture shopping, home decoration, and NPC relationships.";
            manifest.MvpGoal = "Spawn in the central plaza, walk around town, talk to NPCs, accept quests, earn coins, buy furniture, return home, place furniture, and save the result.";
            manifest.CoreLoop = "Explore town -> accept NPC/board quest -> complete a small task -> gain town coins/favor/items -> buy furniture -> decorate rough starter home -> raise warmth -> unlock more tasks, furniture, and dialogue.";
            manifest.PriorityQuestIds = new[] { "Q001", "Q002", "Q003", "Q004", "Q005" };

            CreateLightingAndCamera(root.transform);
            CreateMap(root.transform);
            CreateBuildings(root.transform);
            CreateNpcs(root.transform);
            CreateQuestObjects(root.transform);
            CreateFirstFiveQuestProps(root.transform);
            CreateHomeInterior(root.transform);
            CreateFurnitureShopCatalog(root.transform);
            CreateUiReference(root.transform);
            CreatePlayerAndRuntime(root.transform);
            CreateCharacterSkinSystem(root.transform);
            CreateMapSystem(root.transform);
            CreateHomeProgressSystem(root.transform);
            CreateQuestGuidanceSystem(root.transform);
            CreateTownDetailProps(root.transform);
            CreatePhotoModeSystem(root.transform);
            CreateSettingsSystem(root.transform);
            CreateFriendVisitSystem(root.transform);
            LinkVisibleDoors();

            Directory.CreateDirectory(Path.GetDirectoryName(ScenePath));
            EditorSceneManager.SaveScene(scene, ScenePath);
            AddSceneToBuildSettings(ScenePath);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            Debug.Log("[BubuTown] Visible prototype scene created: " + ScenePath);
        }

