            {
                throw new System.Exception("[BubuTown] Missing scene: " + ScenePath);
            }

            EnsureFolders();
            EnsureMaterials();
            EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);

            var player = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/08_Player_And_Runtime/Player_Start_Bubu");
            if (player == null)
            {
                throw new System.Exception("[BubuTown] Missing player root for DaMogu locomotion prototype.");
            }

            ConfigureDaMoguLocomotionPrototype(player);
            EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            Debug.Log("[BubuTown] DaMogu locomotion prototype upgraded.");
        }

