        [MenuItem("BubuTown/Build Visual Audit Contact Sheet")]
        public static void BuildVisualAuditContactSheet()
        {
            const int columns = 3;
            const int tileWidth = 520;
            const int tileHeight = 325;
            const int gutter = 12;
            var rows = Mathf.CeilToInt(VisualAuditPreviewFiles.Length / (float)columns);
            var sheetWidth = columns * tileWidth + (columns + 1) * gutter;
            var sheetHeight = rows * tileHeight + (rows + 1) * gutter;
            var sheet = new Texture2D(sheetWidth, sheetHeight, TextureFormat.RGB24, false);
            var background = new Color32(26, 30, 34, 255);
            var missing = new Color32(88, 42, 92, 255);

            FillTexture(sheet, background);
            for (var i = 0; i < VisualAuditPreviewFiles.Length; i++)
            {
                var sourcePath = "Assets/BubuTown/Docs/" + VisualAuditPreviewFiles[i];
                var source = LoadReadablePreview(sourcePath);
                var row = i / columns;
                var column = i % columns;
                var x = gutter + column * (tileWidth + gutter);
                var y = sheetHeight - gutter - tileHeight - row * (tileHeight + gutter);
                if (source == null)
                {
                    FillRect(sheet, x, y, tileWidth, tileHeight, missing);
                    continue;
                }

                CopyScaled(source, sheet, x, y, tileWidth, tileHeight);
                Object.DestroyImmediate(source);
            }

            var outputPath = "Assets/BubuTown/Docs/VisualAuditContactSheet.png";
            Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
            File.WriteAllBytes(outputPath, sheet.EncodeToPNG());
            Object.DestroyImmediate(sheet);
            AssetDatabase.ImportAsset(outputPath);
            Debug.Log("[BubuTown] Visual audit contact sheet captured: " + outputPath);
        }

        [MenuItem("BubuTown/Build Preview Anomaly Report")]
        public static void BuildPreviewAnomalyReport()
        {
            var report = new System.Text.StringBuilder();
            report.AppendLine("# Preview Anomaly Report");
            report.AppendLine();
            report.AppendLine("Generated from current preview PNGs. Thresholds are simple gates for obvious visual regressions.");
            report.AppendLine();
            report.AppendLine("| Preview | Magenta % | Empty blue/green % | Very dark % | Gate |");
            report.AppendLine("| --- | ---: | ---: | ---: | --- |");

            var pass = true;
            foreach (var preview in VisualAuditPreviewFiles)
            {
                var texture = LoadReadablePreview("Assets/BubuTown/Docs/" + preview);
                if (texture == null)
                {
                    report.AppendLine("| " + preview + " | n/a | n/a | n/a | MISSING |");
                    pass = false;
                    continue;
                }

                var stats = AnalyzePreviewAnomalies(texture);
                Object.DestroyImmediate(texture);
                var gate = stats.MagentaRatio <= 0.01f && stats.EmptyBackgroundRatio <= EmptyBackgroundThreshold(preview) ? "PASS" : "CHECK";
                if (gate != "PASS")
                {
                    pass = false;
                }

                report.AppendLine("| " + preview + " | " + Percent(stats.MagentaRatio) + " | " + Percent(stats.EmptyBackgroundRatio) + " | " + Percent(stats.VeryDarkRatio) + " | " + gate + " |");
            }

            report.AppendLine();
            report.AppendLine(pass ? "Overall: PASS" : "Overall: CHECK");

            var outputPath = "Assets/BubuTown/Docs/PreviewAnomalyReport.md";
            Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
            File.WriteAllText(outputPath, report.ToString(), System.Text.Encoding.UTF8);
            AssetDatabase.ImportAsset(outputPath);
            BubuTownAssetStoreCityIntegrator.GenerateModernVisualQualityGateReport();
            Debug.Log("[BubuTown] Preview anomaly report written: " + outputPath);
        }

        private static void CapturePreview(string outputPath, Vector3 cameraPosition, Vector3 lookAt, float fieldOfView, string logLabel)
        {
            CapturePreview(outputPath, cameraPosition, lookAt, fieldOfView, logLabel, new Color(0.58f, 0.75f, 0.92f));
        }

        private static void CapturePreview(string outputPath, Vector3 cameraPosition, Vector3 lookAt, float fieldOfView, string logLabel, Color backgroundColor)
        {
            if (!File.Exists(ScenePath))
            {
                throw new System.Exception("[BubuTown] Missing scene: " + ScenePath);
            }

            EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
            var cameraObject = new GameObject("Modern_City_Preview_Camera");
            var camera = cameraObject.AddComponent<Camera>();
            camera.transform.position = cameraPosition;
            camera.transform.rotation = Quaternion.LookRotation(lookAt - cameraPosition, Vector3.up);
            camera.fieldOfView = fieldOfView;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = backgroundColor;
            camera.allowHDR = true;
            camera.allowMSAA = true;

            var renderTexture = new RenderTexture(1600, 1000, 24);
            renderTexture.antiAliasing = 4;
            camera.targetTexture = renderTexture;
            camera.Render();

            RenderTexture.active = renderTexture;
            var image = new Texture2D(renderTexture.width, renderTexture.height, TextureFormat.RGB24, false);
            image.ReadPixels(new Rect(0, 0, renderTexture.width, renderTexture.height), 0, 0);
            image.Apply();

            Directory.CreateDirectory(Path.GetDirectoryName(outputPath));
            File.WriteAllBytes(outputPath, image.EncodeToPNG());

            RenderTexture.active = null;
            camera.targetTexture = null;
            Object.DestroyImmediate(renderTexture);
            Object.DestroyImmediate(image);
            Object.DestroyImmediate(cameraObject);
            AssetDatabase.ImportAsset(outputPath);
            Debug.Log("[BubuTown] " + logLabel + " captured: " + outputPath);
        }

        private static void FillTexture(Texture2D texture, Color32 color)
        {
            var pixels = new Color32[texture.width * texture.height];
            for (var i = 0; i < pixels.Length; i++)
            {
                pixels[i] = color;
            }

            texture.SetPixels32(pixels);
            texture.Apply(false);
        }

        private static void FillRect(Texture2D texture, int x, int y, int width, int height, Color32 color)
        {
            for (var py = 0; py < height; py++)
            {
                for (var px = 0; px < width; px++)
                {
                    texture.SetPixel(x + px, y + py, color);
                }
            }

            texture.Apply(false);
        }

        private static void CopyScaled(Texture2D source, Texture2D target, int x, int y, int width, int height)
        {
            for (var py = 0; py < height; py++)
            {
                var v = py / (height - 1f);
                for (var px = 0; px < width; px++)
                {
                    var u = px / (width - 1f);
                    target.SetPixel(x + px, y + py, source.GetPixelBilinear(u, v));
                }
            }

            target.Apply(false);
        }

        private static Texture2D LoadReadablePreview(string path)
        {
            if (!File.Exists(path))
            {
                return null;
            }

            var texture = new Texture2D(2, 2, TextureFormat.RGB24, false);
            if (!texture.LoadImage(File.ReadAllBytes(path)))
            {
                Object.DestroyImmediate(texture);
                return null;
            }

            return texture;
        }

        private static PreviewAnomalyStats AnalyzePreviewAnomalies(Texture2D texture)
        {
            var pixels = texture.GetPixels32();
            var magenta = 0;
            var emptyBackground = 0;
            var veryDark = 0;
            for (var i = 0; i < pixels.Length; i++)
            {
                var pixel = pixels[i];
                if (pixel.r > 220 && pixel.g < 70 && pixel.b > 190)
                {
                    magenta++;
                }

                if ((pixel.b > 210 && pixel.r >= 105 && pixel.r <= 185 && pixel.g >= 145 && pixel.g <= 220)
                    || (pixel.g > 210 && pixel.r >= 80 && pixel.r <= 165 && pixel.b >= 105 && pixel.b <= 195))
                {
                    emptyBackground++;
                }

                if (pixel.r < 18 && pixel.g < 18 && pixel.b < 18)
                {
                    veryDark++;
                }
            }

            var total = Mathf.Max(1, pixels.Length);
            return new PreviewAnomalyStats
            {
                MagentaRatio = magenta / (float)total,
                EmptyBackgroundRatio = emptyBackground / (float)total,
                VeryDarkRatio = veryDark / (float)total
            };
        }

        private static string Percent(float ratio)
        {
            return (ratio * 100f).ToString("0.00") + "%";
        }

        private static float EmptyBackgroundThreshold(string preview)
        {
            if (preview == "ModernCityPreview.png")
            {
                return 0.12f;
            }

            if (preview == "StreetLevelPreview.png")
            {
                return 0.08f;
            }

            if (preview == "B1GarageInteriorPreview.png")
            {
                return 0.09f;
            }

            return 0.06f;
        }

        private struct PreviewAnomalyStats
        {
            public float MagentaRatio;
            public float EmptyBackgroundRatio;
            public float VeryDarkRatio;
        }

        private static void CreateLightingAndCamera(Transform root)
        {
            QualitySettings.antiAliasing = 4;
            QualitySettings.anisotropicFiltering = AnisotropicFiltering.ForceEnable;

            var group = Group(root, "00_Lighting_And_Camera");
            var cameraObject = new GameObject("Main Camera", typeof(Camera), typeof(AudioListener));
            cameraObject.tag = "MainCamera";
            cameraObject.transform.SetParent(group, false);
            cameraObject.transform.position = new Vector3(0f, 48f, -62f);
            cameraObject.transform.rotation = Quaternion.Euler(52f, 0f, 0f);
            cameraObject.GetComponent<Camera>().fieldOfView = 42f;
            cameraObject.GetComponent<Camera>().clearFlags = CameraClearFlags.SolidColor;
            cameraObject.GetComponent<Camera>().backgroundColor = new Color(0.60f, 0.78f, 0.95f);
            cameraObject.GetComponent<Camera>().allowHDR = true;
            cameraObject.GetComponent<Camera>().allowMSAA = true;

            var sun = new GameObject("Warm_Directional_Light", typeof(Light));
            sun.transform.SetParent(group, false);
            sun.transform.rotation = Quaternion.Euler(48f, -34f, 0f);
            var light = sun.GetComponent<Light>();
            light.type = LightType.Directional;
            light.intensity = 1.15f;
            light.color = new Color(1.0f, 0.91f, 0.78f);
            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Trilight;
            RenderSettings.ambientSkyColor = new Color(0.62f, 0.74f, 0.88f);
            RenderSettings.ambientEquatorColor = new Color(0.46f, 0.50f, 0.55f);
            RenderSettings.ambientGroundColor = new Color(0.30f, 0.31f, 0.33f);
            RenderSettings.fog = true;
            RenderSettings.fogColor = new Color(0.62f, 0.74f, 0.86f);
            RenderSettings.fogMode = FogMode.ExponentialSquared;
            RenderSettings.fogDensity = 0.0055f;

            var fill = new GameObject("Soft_City_Fill_Light", typeof(Light));
            fill.transform.SetParent(group, false);
            fill.transform.position = new Vector3(-18f, 18f, -18f);
            var fillLight = fill.GetComponent<Light>();
            fillLight.type = LightType.Point;
            fillLight.range = 65f;
            fillLight.intensity = 0.55f;
            fillLight.color = new Color(0.62f, 0.78f, 1f);

            var warmShopLight = new GameObject("Warm_Shopfront_Ambience_Light", typeof(Light));
            warmShopLight.transform.SetParent(group, false);
            warmShopLight.transform.position = new Vector3(-4f, 6f, 4f);
            var warm = warmShopLight.GetComponent<Light>();
            warm.type = LightType.Point;
            warm.range = 42f;
            warm.intensity = 0.38f;
            warm.color = new Color(1f, 0.78f, 0.42f);

            var reflectionProbe = new GameObject("City_Reflection_Probe", typeof(ReflectionProbe));
            reflectionProbe.transform.SetParent(group, false);
            reflectionProbe.transform.position = new Vector3(0f, 10f, 0f);
            var probe = reflectionProbe.GetComponent<ReflectionProbe>();
            probe.size = new Vector3(110f, 55f, 110f);
            probe.intensity = 0.45f;
            probe.resolution = 128;
            probe.mode = UnityEngine.Rendering.ReflectionProbeMode.Realtime;
            probe.refreshMode = UnityEngine.Rendering.ReflectionProbeRefreshMode.OnAwake;

            CreateModernRenderingQualityPass(group);
        }

        private static void CreateModernRenderingQualityPass(Transform parent)
        {
            var quality = new GameObject("Modern_Rendering_Quality_Pass");
            quality.transform.SetParent(parent, false);

            ReflectionProbeAnchor(quality.transform, "North_Glass_District_Reflection_Probe", new Vector3(-24f, 12f, 31f), new Vector3(42f, 34f, 30f), 0.55f);
            ReflectionProbeAnchor(quality.transform, "East_Commercial_Reflection_Probe", new Vector3(35f, 10f, -18f), new Vector3(34f, 30f, 42f), 0.5f);
            ReflectionProbeAnchor(quality.transform, "Underground_Spaces_Reflection_Probe", new Vector3(22f, -1.2f, -44f), new Vector3(36f, 12f, 38f), 0.35f);

            AreaQualityLight(quality.transform, "Cool_Glass_Facade_Key_Light", new Vector3(18f, 12f, -12f), new Vector3(58f, -28f, 0f), 0.34f, new Color(0.58f, 0.76f, 1f));
