            var bootstrapObject = new GameObject("Runtime_Visual_Quality_Bootstrap");
            bootstrapObject.transform.SetParent(quality.transform, false);
            bootstrapObject.transform.position = new Vector3(-41.8f, 1.2f, 46f);
            var bootstrap = bootstrapObject.AddComponent<BubuTownVisualQualityBootstrap>();
