            Cube(quality.transform, "Runtime_Shadow_LOD_Audit_Marker", new Vector3(-40.4f, 1.2f, 46f), new Vector3(1.1f, 2.4f, 0.18f), "Green");
            Cube(quality.transform, "Runtime_Texture_FullRes_Audit_Marker", new Vector3(-39f, 1.2f, 46f), new Vector3(1.1f, 2.4f, 0.18f), "Yellow");
            CreateModernAssetQualityGatePass(quality.transform);
