        private static void AssetQualityGate(Transform parent, string name, Vector3 position, string gateId, string category, string textureRule, string source, int priority, bool rejectPixelated, bool attributionCheck, string accent)
        {
            var gate = new GameObject(name);
            gate.transform.SetParent(parent, false);
            gate.transform.localPosition = position;
            var marker = gate.AddComponent<BubuTownAssetQualityGateMarker>();
            marker.GateId = gateId;
            marker.Category = category;
            marker.MinimumTextureRule = textureRule;
            marker.PreferredSource = source;
            marker.ReplacementPriority = priority;
            marker.RejectPixelatedTextures = rejectPixelated;
            marker.RequiresAttributionCheck = attributionCheck;

            Cube(gate.transform, "Quality_Gate_Dark_Backplate", new Vector3(0f, 1.24f, 0f), new Vector3(1.1f, 2.15f, 0.16f), "DarkGlass");
            Cube(gate.transform, "Quality_Gate_Status_Strip", new Vector3(0f, 2.16f, -0.11f), new Vector3(0.82f, 0.11f, 0.045f), accent);
