            Cube(gate.transform, "Quality_Gate_URP_Dot", new Vector3(0.02f, 1.22f, -0.12f), new Vector3(0.18f, 0.18f, 0.04f), "CoolLight");
            Cube(gate.transform, "Quality_Gate_License_Dot", new Vector3(0.28f, 1.22f, -0.12f), new Vector3(0.18f, 0.18f, 0.04f), "WarmLight");
