        private static void ArtReplacementAudit(Transform parent, string name, Vector3 position, string auditId, string targetArea, string replacementCategory, string acceptanceRule, string suggestedSource, int priority, bool requiresUrpMaterial, bool rejectPixelatedTextures, bool publicRepoSafe, string accent)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.localPosition = position;

            var marker = node.AddComponent<BubuTownArtReplacementAuditMarker>();
            marker.AuditId = auditId;
            marker.TargetArea = targetArea;
            marker.ReplacementCategory = replacementCategory;
            marker.AcceptanceRule = acceptanceRule;
            marker.SuggestedSource = suggestedSource;
            marker.Priority = priority;
            marker.RequiresUrpMaterial = requiresUrpMaterial;
            marker.RejectPixelatedTextures = rejectPixelatedTextures;
            marker.PublicRepoSafe = publicRepoSafe;

            Cube(node.transform, "Audit_Node_Dark_Backplate", new Vector3(0f, 1.1f, 0f), new Vector3(1.05f, 1.9f, 0.14f), "DarkGlass");
            Cube(node.transform, "Audit_Node_Priority_Strip", new Vector3(0f, 1.92f, -0.1f), new Vector3(0.78f, 0.1f, 0.04f), accent);
            Cube(node.transform, "Audit_Node_URP_Dot", new Vector3(-0.25f, 1.08f, -0.11f), new Vector3(0.16f, 0.16f, 0.04f), "CoolLight");
            Cube(node.transform, "Audit_Node_Texture_Dot", new Vector3(0f, 1.08f, -0.11f), new Vector3(0.16f, 0.16f, 0.04f), "WarmLight");
            Cube(node.transform, "Audit_Node_RepoSafe_Dot", new Vector3(0.25f, 1.08f, -0.11f), new Vector3(0.16f, 0.16f, 0.04f), "Green");
            EmptyMarker(node.transform, "Future_Audit_Runtime_Query_Hook", new Vector3(0f, 0.35f, -0.55f));
        }

        private static void CreateCityPerformanceStreamingPass(Transform parent)
        {
            var perf = new GameObject("City_Performance_Streaming_Pass");
            perf.transform.SetParent(parent, false);

            var surface = PerformanceSector(perf.transform, "PerfSector_Surface_Core", "surface_core", "Surface core city", new Vector3(0f, 0f, 0f), new Vector3(48f, 0.045f, 48f), "CoolLight", 520, 18, false, true);
            var skyline = PerformanceSector(perf.transform, "PerfSector_Skyline_Ring", "skyline_ring", "Skyline ring", new Vector3(0f, 0f, 43.5f), new Vector3(82f, 0.045f, 9f), "Glass", 430, 12, true, true);
            var garage = PerformanceSector(perf.transform, "PerfSector_B1_Garage", "garage_b1", "B1 garage", new Vector3(30.4f, -3.55f, -45.2f), new Vector3(32f, 0.045f, 24f), "WarmLight", 240, 14, true, false);

            surface.RuntimeHooks = new[] { EmptyMarker(surface.transform, "Future_Surface_Core_Culling_Hook", new Vector3(0f, 0.35f, 0f)) };
            skyline.RuntimeHooks = new[] { EmptyMarker(skyline.transform, "Future_Skyline_LOD_Stream_Hook", new Vector3(0f, 0.35f, 0f)) };
            garage.RuntimeHooks = new[] { EmptyMarker(garage.transform, "Future_B1_Light_Cluster_Culling_Hook", new Vector3(0f, 0.35f, 0f)) };

            var lodRoot = new GameObject("LOD_Tower_Proxy_Audit");
            lodRoot.transform.SetParent(perf.transform, false);
            lodRoot.transform.localPosition = new Vector3(-44.2f, 0f, 33.6f);
            var lod0 = Cube(lodRoot.transform, "LOD0_Glass_Tower_Proxy", new Vector3(0f, 3.2f, 0f), new Vector3(1.25f, 6.4f, 1.25f), "Glass");
            var lod1 = Cube(lodRoot.transform, "LOD1_Simple_Tower_Proxy", new Vector3(2.2f, 2.1f, 0f), new Vector3(0.9f, 4.2f, 0.9f), "Blue");
            var group = lodRoot.AddComponent<LODGroup>();
            group.SetLODs(new[]
            {
                new LOD(0.55f, new[] { lod0.GetComponent<Renderer>() }),
                new LOD(0.18f, new[] { lod1.GetComponent<Renderer>() })
