            group.RecalculateBounds();

            Cube(perf.transform, "Streaming_Boundary_Audit_Panel", new Vector3(-43f, 1.15f, 31.5f), new Vector3(3.4f, 2.3f, 0.16f), "DarkGlass");
            Cube(perf.transform, "Streaming_Boundary_Cyan_Status", new Vector3(-43f, 2.15f, 31.38f), new Vector3(2.7f, 0.12f, 0.055f), "NeonCyan");
            EmptyMarker(perf.transform, "Future_World_Streaming_Runtime_Hook", new Vector3(-43f, 0.35f, 30.7f));
            EmptyMarker(perf.transform, "Future_LOD_Budget_Report_Hook", new Vector3(-41.6f, 0.35f, 30.7f));
            Label(perf.transform, "Performance_Streaming_Label", "performance streaming\nsectors / budgets / LOD audit", new Vector3(-43f, 2.75f, 31.2f), 0.13f);
        }

        private static BubuTownPerformanceBudgetMarker PerformanceSector(Transform parent, string name, string sectorId, string displayName, Vector3 position, Vector3 footprint, string accent, int maxRenderers, int maxLights, bool streamingBoundary, bool requiresLod)
        {
            var sector = new GameObject(name);
            sector.transform.SetParent(parent, false);
            sector.transform.localPosition = position;
            var lineY = 0.24f;
            Cube(sector.transform, "Sector_Accent_North", new Vector3(0f, 0.24f, footprint.z * 0.5f), new Vector3(footprint.x, 0.03f, 0.08f), accent);
            Cube(sector.transform, "Sector_Accent_South", new Vector3(0f, 0.24f, -footprint.z * 0.5f), new Vector3(footprint.x, 0.03f, 0.08f), accent);
            Cube(sector.transform, "Sector_Accent_East", new Vector3(footprint.x * 0.5f, lineY, 0f), new Vector3(0.08f, 0.03f, footprint.z), accent);
            Cube(sector.transform, "Sector_Accent_West", new Vector3(-footprint.x * 0.5f, lineY, 0f), new Vector3(0.08f, 0.03f, footprint.z), accent);
            Cube(sector.transform, "Sector_Corner_NW", new Vector3(-footprint.x * 0.5f, lineY + 0.04f, footprint.z * 0.5f), new Vector3(0.48f, 0.07f, 0.48f), accent);
            Cube(sector.transform, "Sector_Corner_NE", new Vector3(footprint.x * 0.5f, lineY + 0.04f, footprint.z * 0.5f), new Vector3(0.48f, 0.07f, 0.48f), accent);
            Cube(sector.transform, "Sector_Corner_SW", new Vector3(-footprint.x * 0.5f, lineY + 0.04f, -footprint.z * 0.5f), new Vector3(0.48f, 0.07f, 0.48f), accent);
            Cube(sector.transform, "Sector_Corner_SE", new Vector3(footprint.x * 0.5f, lineY + 0.04f, -footprint.z * 0.5f), new Vector3(0.48f, 0.07f, 0.48f), accent);
            Cube(sector.transform, "Sector_Load_Status_Puck", new Vector3(-footprint.x * 0.46f, 0.3f, -footprint.z * 0.42f), new Vector3(0.56f, 0.06f, 0.56f), accent);
            var marker = sector.AddComponent<BubuTownPerformanceBudgetMarker>();
            marker.SectorId = sectorId;
            marker.DisplayName = displayName;
            marker.TargetMaxRenderers = maxRenderers;
            marker.TargetMaxLights = maxLights;
            marker.IsStreamingBoundary = streamingBoundary;
            marker.RequiresLodSwap = requiresLod;
            Label(sector.transform, "Sector_Budget_Label", displayName + "\nrenderers " + maxRenderers + " / lights " + maxLights, new Vector3(0f, 0.72f, -footprint.z * 0.5f - 0.5f), 0.1f);
            return marker;
        }

