        private static GameObject NightReadabilityZone(Transform parent, string name, Vector3 position, string zoneId, string zoneType, string displayName, string linkedSceneAreaId, float targetIntensity, bool requiresReflectionProbe, bool runtimeTunable, string accent)
        {
            var zone = new GameObject(name);
            zone.transform.SetParent(parent, false);
            zone.transform.position = position;
            var marker = zone.AddComponent<BubuTownNightReadabilityMarker>();
            marker.ZoneId = zoneId;
            marker.ZoneType = zoneType;
            marker.DisplayName = displayName;
            marker.LinkedSceneAreaId = linkedSceneAreaId;
            marker.TargetIntensity = targetIntensity;
            marker.RequiresReflectionProbe = requiresReflectionProbe;
            marker.RuntimeTunable = runtimeTunable;
            Cube(zone.transform, "NightZone_Status_Puck", new Vector3(-0.72f, 0.32f, -0.58f), new Vector3(0.34f, 0.055f, 0.34f), accent);
            EmptyMarker(zone.transform, "Future_NightZone_Runtime_Hook", new Vector3(0f, 0.35f, -0.82f));
            return zone;
        }

        private static void ReflectionProbeAnchor(Transform parent, string name, Vector3 position, Vector3 size, float intensity)
        {
            var probeObject = new GameObject(name, typeof(ReflectionProbe));
            probeObject.transform.SetParent(parent, false);
            probeObject.transform.position = position;
            var probe = probeObject.GetComponent<ReflectionProbe>();
            probe.size = size;
            probe.intensity = intensity;
            probe.resolution = 128;
            probe.mode = UnityEngine.Rendering.ReflectionProbeMode.Realtime;
            probe.refreshMode = UnityEngine.Rendering.ReflectionProbeRefreshMode.OnAwake;
        }

        private static void AreaQualityLight(Transform parent, string name, Vector3 position, Vector3 rotation, float intensity, Color color)
        {
            var lightObject = new GameObject(name, typeof(Light));
            lightObject.transform.SetParent(parent, false);
            lightObject.transform.position = position;
            lightObject.transform.rotation = Quaternion.Euler(rotation);
            var light = lightObject.GetComponent<Light>();
            light.type = LightType.Directional;
            light.intensity = intensity;
            light.color = color;
        }

