        private static void CreateModernPlazaScaleCompositionPass(Transform parent)
        {
            var plaza = new GameObject("Modern_Plaza_Scale_Composition_Pass");
            plaza.transform.SetParent(parent, false);

            Cylinder(plaza.transform, "Low_Profile_Glass_Water_Ring", new Vector3(0f, 0.28f, 0f), new Vector3(6.4f, 0.08f, 6.4f), "Glass");
            Cylinder(plaza.transform, "Thin_Cyan_Fountain_Light_Ring", new Vector3(0f, 0.34f, 0f), new Vector3(4.9f, 0.035f, 4.9f), "CoolLight");
            Cylinder(plaza.transform, "Calm_Center_Water_Disc", new Vector3(0f, 0.39f, 0f), new Vector3(2.65f, 0.045f, 2.65f), "Water");

            for (var i = 0; i < 6; i++)
            {
                var angle = i * Mathf.PI * 2f / 6f;
                var x = Mathf.Cos(angle) * 7.6f;
                var z = Mathf.Sin(angle) * 7.6f;
                var bench = new GameObject("Plaza_Modern_Bench_Arc_" + i);
                bench.transform.SetParent(plaza.transform, false);
                bench.transform.localPosition = new Vector3(x, 0f, z);
                bench.transform.localRotation = Quaternion.Euler(0f, -angle * Mathf.Rad2Deg + 90f, 0f);
                Cube(bench.transform, "Arc_Bench_MicroConcrete_Base", new Vector3(0f, 0.28f, 0f), new Vector3(2.15f, 0.26f, 0.42f), "MicroConcrete");
                Cube(bench.transform, "Arc_Bench_Glass_Back", new Vector3(0f, 0.68f, 0.24f), new Vector3(2.05f, 0.52f, 0.055f), "Glass");
                Cube(bench.transform, "Arc_Bench_Cool_Underlight", new Vector3(0f, 0.41f, -0.24f), new Vector3(1.55f, 0.04f, 0.04f), "CoolLight");
            }

            for (var i = 0; i < 8; i++)
            {
                var angle = i * Mathf.PI * 2f / 8f;
                var x = Mathf.Cos(angle) * 10.8f;
                var z = Mathf.Sin(angle) * 10.8f;
                var line = Cube(plaza.transform, "Plaza_Radial_Thin_Light_Line_" + i, new Vector3(x * 0.5f, 0.265f, z * 0.5f), new Vector3(0.08f, 0.025f, 5.1f), i % 2 == 0 ? "CoolLight" : "WarmLight");
                line.transform.localRotation = Quaternion.Euler(0f, -angle * Mathf.Rad2Deg, 0f);
            }

            EmptyMarker(plaza.transform, "Future_Plaza_Center_Art_Swap_Hook", new Vector3(0f, 0.35f, 0f));
            EmptyMarker(plaza.transform, "Future_Plaza_Seasonal_Event_Hook", new Vector3(0f, 0.35f, 7.6f));
            CreatePlazaCivicDetailAndEventInfrastructurePass(plaza.transform);
        }

