            Cube(kiosk.transform, "CivicKiosk_GarageRoute_Row", new Vector3(0f, 1.36f, -0.12f), new Vector3(0.7f, 0.065f, 0.045f), "NeonCyan");
            Cube(kiosk.transform, "CivicKiosk_HomeDecor_Row", new Vector3(0f, 0.94f, -0.12f), new Vector3(0.54f, 0.065f, 0.045f), "Green");
