            var seating = StreetFurniture(civic.transform, "Plaza_Shaded_Social_Seating_Node", new Vector3(-6.8f, 0f, 5.2f), 28f, "plaza.social.shaded_seating", "ShadedSeating", "Plaza shaded social seating node", "Future_Plaza_Npc_Social_Daily_Hook", true, true);
            Cube(seating.transform, "ShadedSeating_Rounded_Paver_Island", new Vector3(0f, 0.17f, 0f), new Vector3(5.6f, 0.065f, 2.45f), "MicroConcrete");
            Cube(seating.transform, "ShadedSeating_Thin_Glass_Canopy", new Vector3(0f, 2.42f, 0.15f), new Vector3(5.9f, 0.12f, 2.55f), "Glass");
            Cube(seating.transform, "ShadedSeating_Canopy_Warm_Edge", new Vector3(0f, 2.48f, -1.08f), new Vector3(5.2f, 0.055f, 0.055f), "WarmLight");
            for (var i = 0; i < 3; i++)
            {
                var x = -1.8f + i * 1.8f;
                Cube(seating.transform, "Social_Seat_Wood_Slat_" + i, new Vector3(x, 0.54f, -0.3f), new Vector3(1.22f, 0.18f, 0.5f), "Wood");
                Cube(seating.transform, "Social_Seat_Charging_Dot_" + i, new Vector3(x, 0.66f, -0.58f), new Vector3(0.18f, 0.035f, 0.055f), i % 2 == 0 ? "CoolLight" : "WarmLight");
                Planter(seating.transform, "Social_Seating_Planter_" + i, new Vector3(x, 0f, 0.82f));
            }
            EmptyMarker(seating.transform, "Future_Plaza_Npc_Social_Point_A", new Vector3(-1.2f, 0.35f, -1.05f));
            EmptyMarker(seating.transform, "Future_Plaza_Npc_Social_Point_B", new Vector3(1.2f, 0.35f, -1.05f));

            var power = new GameObject("Plaza_Event_Power_Floorbox_Node");
            power.transform.SetParent(civic.transform, false);
            power.transform.localPosition = new Vector3(0f, 0f, 8.2f);
            var device = power.AddComponent<BubuTownCityDeviceMarker>();
            device.DeviceId = "plaza.event.power_floorbox";
            device.DeviceType = "EventPowerFloorbox";
            device.DisplayName = "Plaza event power floorbox node";
            device.LinkedQuestHookId = "Future_Plaza_Event_Setup_Task_Hook";
            device.RequiresMaintenance = true;
            device.VisibleOnCityMap = true;
            Cube(power.transform, "PowerFloorbox_Recessed_Metal_Cover", new Vector3(0f, 0.225f, 0f), new Vector3(1.55f, 0.04f, 1.05f), "Metal");
            Cube(power.transform, "PowerFloorbox_Cyan_Service_Line", new Vector3(0f, 0.255f, -0.42f), new Vector3(1.22f, 0.018f, 0.045f), "NeonCyan");
            Cube(power.transform, "PowerFloorbox_Warm_Locked_Status", new Vector3(-0.52f, 0.262f, 0.28f), new Vector3(0.28f, 0.018f, 0.18f), "WarmLight");
            var servicePanel = Cube(power.transform, "PowerFloorbox_Service_Panel_Interactable", new Vector3(0.62f, 0.36f, 0.24f), new Vector3(0.34f, 0.22f, 0.12f), "DarkGlass");
