            EmptyMarker(civic.transform, "Future_Plaza_Civic_Runtime_Index", new Vector3(5.6f, 0.35f, 6.9f));
            EmptyMarker(civic.transform, "Future_Plaza_Civic_FreeAsset_Swap_Index", new Vector3(4.2f, 0.35f, 6.9f));
            PointLight(civic.transform, "Plaza_Civic_Warm_Readability_Light", new Vector3(-2.8f, 2.7f, 5.4f), 8.4f, 0.24f, new Color(1f, 0.74f, 0.42f));
