            DeprioritizeLegacyBuildingVisuals(group, legacyStartIndex);
            Park(group, new Vector3(32f, 0f, 22f));
        }

        private static void DeprioritizeLegacyBuildingVisuals(Transform group, int startIndex)
        {
            var legacyOffset = new Vector3(0f, 0f, 180f);
            for (var i = startIndex; i < group.childCount; i++)
            {
                var child = group.GetChild(i);
                child.localPosition += legacyOffset;
            }
            EmptyMarker(group, "Legacy_ModernCity_Visuals_Deprioritized_Offset_Note", new Vector3(0f, 0.35f, 168f));
            Label(group, "Legacy_ModernCity_Visuals_Deprioritized_Label", "legacy city layers moved out of StarBay main view\nkept only as replacement candidates / validation anchors", new Vector3(0f, 1.2f, 168f), 0.15f);
        }

