        private static void CreateDecorationGhostPreview(Transform grid, BubuTownDecorationGrid decorationGrid)
        {
            var ghost = new GameObject("Placement_Ghost_Preview");
            ghost.transform.SetParent(grid, false);
            ghost.transform.localPosition = decorationGrid.LocalPositionForIndex(0);
            ghost.transform.localRotation = Quaternion.identity;
            decorationGrid.PreviewRoot = ghost.transform;
            var preview = BubuTownFurnitureVisuals.CreatePlacedFurniture("fur_small_chair", ghost.transform, Vector3.zero);
            preview.name = "Preview_fur_small_chair";
            Label(ghost.transform, "Ghost_Preview_Label", "装修预览挂点\n方向键选格 / Z-X 换家具\nE 确认 / R 旋转", new Vector3(0f, 1.7f, 0f), 0.18f);
        }

