        private static void CreatePlayerAndRuntime(Transform root)
        {
            var group = Group(root, "08_Player_And_Runtime");

            var player = GameObject.CreatePrimitive(PrimitiveType.Capsule);
            player.name = "Player_Start_Bubu";
            player.transform.SetParent(group, false);
            player.transform.position = new Vector3(0f, 1f, -8f);
            player.transform.localScale = new Vector3(0.9f, 1.1f, 0.9f);
            ApplyMaterial(player, "Pink");
            Object.DestroyImmediate(player.GetComponent<CapsuleCollider>());
            var character = player.AddComponent<CharacterController>();
            character.center = new Vector3(0f, 1f, 0f);
            character.height = 2f;
            character.radius = 0.45f;
            var controller = player.AddComponent<BubuTownPlayerController>();
            AddSkinSlot(player, "player_bubu", true);
            ConfigureDaMoguLocomotionPrototype(player);
            Label(player.transform, "Player_Label", "布布\nPlayer Start", new Vector3(0f, 2.3f, 0f), 0.28f);

            var camera = GameObject.Find("Main Camera");
            if (camera != null)
            {
                controller.CameraTransform = camera.transform;
                var follow = camera.AddComponent<BubuTownThirdPersonCamera>();
                follow.Target = player.transform;
                follow.Offset = new Vector3(0f, 2.55f, -4.65f);
                follow.Pitch = 14f;
                follow.Yaw = 0f;
            }

            var stateObject = new GameObject("GameState_Manager");
            stateObject.transform.SetParent(group, false);
            stateObject.transform.position = new Vector3(-3f, 0.5f, -10f);
            var state = stateObject.AddComponent<BubuTownGameState>();
            state.TownCoins = 120;
            state.CurrentDay = 1;
            state.HomeWarmthTarget = 12;
            state.LastMessage = "欢迎来到布布的小镇。先和小镇管理员说话吧。";
            state.EnsureFriendshipRecords();

            var interactionObject = new GameObject("Interaction_Manager");
            interactionObject.transform.SetParent(group, false);
            interactionObject.transform.position = new Vector3(-1f, 0.5f, -10f);
            var interaction = interactionObject.AddComponent<BubuTownInteractionSystem>();
            interaction.Player = controller;
            interaction.State = state;
            var grid = GameObject.Find("Decoration_Grid_8x6");
            if (grid != null)
            {
                interaction.HomeGrid = grid.GetComponent<BubuTownDecorationGrid>();
            }

            var hudObject = new GameObject("Runtime_HUD_Manager");
            hudObject.transform.SetParent(group, false);
            hudObject.transform.position = new Vector3(1f, 0.5f, -10f);
            var hud = hudObject.AddComponent<BubuTownRuntimeHud>();
            hud.State = state;
            hud.Interaction = interaction;
            hud.MinimalHudRoot = FindSceneObject("BubuTown_Prototype_All_Visible_Before_Play/07_Minimal_UI_Reference/Bubu_HUD_Canvas/Minimal_HUD_Root");
            hud.MinimapText = FindUiText("Bubu_HUD_Canvas/Minimal_HUD_Root/Top_Left_Minimap_Panel/Minimap_Text");
            hud.MenuText = FindUiText("Bubu_HUD_Canvas/Minimal_HUD_Root/Top_Right_Menu_Button/Menu_Text");
            hud.QuestGuideText = FindUiText("Bubu_HUD_Canvas/Minimal_HUD_Root/Current_Quest_Guide_Panel/Quest_Guide_Text");
            hud.MessageText = FindUiText("Bubu_HUD_Canvas/Minimal_HUD_Root/Bottom_Message_Panel/Message_Text");
            hud.CoinText = FindUiText("Bubu_HUD_Canvas/Minimal_HUD_Root/Coin_Pill/Coin_Text");
            hud.InteractionPromptPanel = FindSceneObject("BubuTown_Prototype_All_Visible_Before_Play/07_Minimal_UI_Reference/Bubu_HUD_Canvas/Minimal_HUD_Root/Interaction_Prompt_Panel");
            hud.InteractionPromptText = FindUiText("Bubu_HUD_Canvas/Minimal_HUD_Root/Interaction_Prompt_Panel/Interaction_Prompt_Text");
            hud.PhotoModePanel = FindSceneObject("BubuTown_Prototype_All_Visible_Before_Play/07_Minimal_UI_Reference/Bubu_HUD_Canvas/Photo_Mode_Panel");
            hud.PhotoModeText = FindUiText("Bubu_HUD_Canvas/Photo_Mode_Panel/Photo_Mode_Text");
            var menuPanel = FindSceneObject("BubuTown_Prototype_All_Visible_Before_Play/07_Minimal_UI_Reference/Bubu_HUD_Canvas/Expanded_Menu_Panel");
            hud.MenuPanel = menuPanel;
            hud.TaskPanelText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Tasks_Panel/Tasks_Text");
            hud.BagPanelText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Bag_Panel/Bag_Text");
            hud.FurniturePanelText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Furniture_Catalog_Panel/Furniture_Catalog_Text");
            hud.DecorPanelText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Decorate_Panel/Decorate_Text");
            hud.RelationshipPanelText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Relationships_Panel/Relationships_Text");
            hud.HomeProgressText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Home_Progress_Panel/Home_Progress_Text");
            hud.MapPanelText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Map_Panel/Map_Text");
            hud.SettingsPanelText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Settings_Panel/Settings_Text");
            hud.PhotoPanelText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Photo_Panel/Photo_Text");
            hud.SavePanelText = FindUiText("Bubu_HUD_Canvas/Expanded_Menu_Panel/Save_Panel/Save_Text");
            hud.DialoguePanel = FindSceneObject("BubuTown_Prototype_All_Visible_Before_Play/07_Minimal_UI_Reference/Bubu_HUD_Canvas/Dialogue_Panel");
            hud.DialogueSpeakerText = FindUiText("Bubu_HUD_Canvas/Dialogue_Panel/Dialogue_Speaker_Text");
            hud.DialogueBodyText = FindUiText("Bubu_HUD_Canvas/Dialogue_Panel/Dialogue_Body_Text");
            hud.DialogueFriendshipText = FindUiText("Bubu_HUD_Canvas/Dialogue_Panel/Dialogue_Friendship_Text");
            hud.DialogueQuestHintText = FindUiText("Bubu_HUD_Canvas/Dialogue_Panel/Dialogue_Quest_Hint_Text");

            var saveObject = new GameObject("Save_Bootstrap_Manager");
            saveObject.transform.SetParent(group, false);
            saveObject.transform.position = new Vector3(3f, 0.5f, -10f);
            var save = saveObject.AddComponent<BubuTownSaveBootstrap>();
            save.State = state;
            if (grid != null)
            {
                save.HomeGrid = grid.GetComponent<BubuTownDecorationGrid>();
            }

            var savePoint = Cube(group, "Home_Save_Point_Visible", new Vector3(-20f, 0.5f, -34f), new Vector3(1.2f, 1f, 1.2f), "Blue");
            AddInteractable(savePoint, BubuTownInteractableType.SavePoint, "HOME_SAVE_POINT", "保存点", "E: save town progress");
            Label(savePoint.transform, "Save_Point_Label", "保存点", new Vector3(0f, 1f, 0f), 0.24f);
        }

        private static void ConfigureDaMoguLocomotionPrototype(GameObject player)
        {
            var rootRenderer = player.GetComponent<Renderer>();
            if (rootRenderer != null)
            {
                rootRenderer.enabled = false;
            }

            RemoveChildIfExists(player.transform, "DaMogu_C_Anime_ThirdPerson_Prototype");
            RemoveChildIfExists(player.transform, "Arrival_Rolling_Suitcase_Prop");

            var visual = new GameObject("DaMogu_C_Anime_ThirdPerson_Prototype");
            visual.transform.SetParent(player.transform, false);
            visual.transform.localPosition = new Vector3(0f, -1.02f, 0f);
            visual.transform.localScale = Vector3.one * 0.92f;

            var hips = Cube(visual.transform, "Slim_Humanoid_Hips", new Vector3(0f, 0.82f, 0f), new Vector3(0.46f, 0.22f, 0.28f), "WhiteCloth");
            var torso = Cube(visual.transform, "Soft_City_Top", new Vector3(0f, 1.12f, 0f), new Vector3(0.5f, 0.64f, 0.24f), "WhiteCloth");
            var jacket = Cube(visual.transform, "PinkWhite_Windbreaker", new Vector3(0f, 1.13f, -0.02f), new Vector3(0.58f, 0.7f, 0.3f), "SoftPink");
            var skirt = Cube(visual.transform, "Sea_Breeze_Skort_Or_Coat_Hem", new Vector3(0f, 0.68f, 0.01f), new Vector3(0.68f, 0.24f, 0.34f), "SoftPink");
            var neck = Cylinder(visual.transform, "Neck", new Vector3(0f, 1.52f, 0f), new Vector3(0.12f, 0.16f, 0.12f), "Skin");
            var head = Sphere(visual.transform, "Head", new Vector3(0f, 1.78f, -0.02f), new Vector3(0.42f, 0.5f, 0.38f), "Skin");
            var hair = Sphere(visual.transform, "Soft_HalfUp_Hair", new Vector3(0f, 1.86f, 0.04f), new Vector3(0.48f, 0.44f, 0.42f), "Hair");
            var hairTail = Cube(visual.transform, "Medium_Hair_Back_Swing_Guide", new Vector3(0f, 1.48f, 0.2f), new Vector3(0.34f, 0.56f, 0.16f), "Hair");
            var facePanel = Cube(visual.transform, "Mature_Anime_Face_Guide", new Vector3(0f, 1.77f, -0.36f), new Vector3(0.28f, 0.18f, 0.025f), "Wall");
            var leftEye = Sphere(visual.transform, "Eye_Left", new Vector3(-0.105f, 1.82f, -0.378f), new Vector3(0.045f, 0.045f, 0.025f), "DarkGlass");
            var rightEye = Sphere(visual.transform, "Eye_Right", new Vector3(0.105f, 1.82f, -0.378f), new Vector3(0.045f, 0.045f, 0.025f), "DarkGlass");
            var mouth = Cube(visual.transform, "Small_Natural_Mouth", new Vector3(0f, 1.69f, -0.385f), new Vector3(0.12f, 0.018f, 0.018f), "Red");
            var leftArm = Cylinder(visual.transform, "Left_Arm_Animation_Guide", new Vector3(-0.39f, 1.08f, -0.01f), new Vector3(0.095f, 0.72f, 0.095f), "SoftPink");
            var rightArm = Cylinder(visual.transform, "Right_Arm_Animation_Guide", new Vector3(0.39f, 1.08f, -0.01f), new Vector3(0.095f, 0.72f, 0.095f), "SoftPink");
            var leftHand = Sphere(visual.transform, "Left_Hand", new Vector3(-0.39f, 0.68f, -0.01f), new Vector3(0.105f, 0.105f, 0.085f), "Skin");
            var rightHand = Sphere(visual.transform, "Right_Hand", new Vector3(0.39f, 0.68f, -0.01f), new Vector3(0.105f, 0.105f, 0.085f), "Skin");
            var leftLeg = Cylinder(visual.transform, "Left_Leg_Animation_Guide", new Vector3(-0.18f, 0.36f, 0f), new Vector3(0.11f, 0.72f, 0.11f), "Skin");
            var rightLeg = Cylinder(visual.transform, "Right_Leg_Animation_Guide", new Vector3(0.18f, 0.36f, 0f), new Vector3(0.11f, 0.72f, 0.11f), "Skin");
            var leftShoe = Cube(visual.transform, "Left_Sneaker", new Vector3(-0.18f, 0.04f, -0.08f), new Vector3(0.18f, 0.08f, 0.3f), "WhiteCloth");
            var rightShoe = Cube(visual.transform, "Right_Sneaker", new Vector3(0.18f, 0.04f, -0.08f), new Vector3(0.18f, 0.08f, 0.3f), "WhiteCloth");
            var backpack = Cube(visual.transform, "Small_Backpack_ThirdPerson_Readable", new Vector3(0f, 1.1f, 0.2f), new Vector3(0.4f, 0.5f, 0.14f), "SeaBlue");

            var createdParts = new[]
            {
                hips, torso, jacket, skirt, neck, head, hair, hairTail, facePanel, leftEye, rightEye, mouth,
                leftArm, rightArm, leftHand, rightHand, leftLeg, rightLeg, leftShoe, rightShoe, backpack
            };
            foreach (var part in createdParts)
            {
                RemoveCollider(part);
            }

            var suitcase = new GameObject("Arrival_Rolling_Suitcase_Prop");
            suitcase.transform.SetParent(player.transform, false);
            suitcase.transform.localPosition = new Vector3(-0.78f, -0.72f, 0.18f);
            suitcase.transform.localRotation = Quaternion.Euler(0f, -12f, 0f);
            Cube(suitcase.transform, "Suitcase_Body", new Vector3(0f, 0.46f, 0f), new Vector3(0.34f, 0.72f, 0.22f), "SeaBlue");
            Cylinder(suitcase.transform, "Suitcase_Handle", new Vector3(0f, 0.93f, -0.03f), new Vector3(0.035f, 0.34f, 0.035f), "Metal");
            Cylinder(suitcase.transform, "Suitcase_Wheel_Left", new Vector3(-0.13f, 0.08f, -0.08f), new Vector3(0.045f, 0.045f, 0.045f), "ConcreteDark");
            Cylinder(suitcase.transform, "Suitcase_Wheel_Right", new Vector3(0.13f, 0.08f, -0.08f), new Vector3(0.045f, 0.045f, 0.045f), "ConcreteDark");
            foreach (Transform part in suitcase.transform)
            {
                RemoveCollider(part.gameObject);
            }

            var locomotion = player.GetComponent<BubuTownLocomotionAnimator>();
            if (locomotion == null)
            {
                locomotion = player.AddComponent<BubuTownLocomotionAnimator>();
            }
            locomotion.VisualRoot = visual.transform;
            locomotion.Head = head.transform;
            locomotion.HairTail = hairTail.transform;
            locomotion.SkirtOrCoat = skirt.transform;
            locomotion.LeftArm = leftArm.transform;
            locomotion.RightArm = rightArm.transform;
            locomotion.LeftLeg = leftLeg.transform;
            locomotion.RightLeg = rightLeg.transform;

            var controller = player.GetComponent<BubuTownPlayerController>();
            if (controller != null)
            {
                controller.WalkSpeed = 3.6f;
                controller.RunSpeed = 6.2f;
                controller.Acceleration = 16f;
                controller.Deceleration = 24f;
                controller.RotationSharpness = 13f;
                controller.LocomotionAnimator = locomotion;
            }

            var character = player.GetComponent<CharacterController>();
            if (character != null)
            {
                character.center = new Vector3(0f, 0f, 0f);
                character.height = 1.8f;
                character.radius = 0.32f;
            }
        }

