        private static void NavigationRouteDebugger(Transform parent, string name, BubuTownNavigationGraph graph, string startAnchorId, string endAnchorId, string[] requiredWaypointAnchorIds, string materialName, Vector3 labelPosition)
        {
            var routeObject = new GameObject(name);
            routeObject.transform.SetParent(parent, false);
            var debugger = routeObject.AddComponent<BubuTownNavigationRouteDebugger>();
            debugger.Graph = graph;
            debugger.StartAnchorId = startAnchorId;
            debugger.EndAnchorId = endAnchorId;
            debugger.RequiredWaypointAnchorIds = requiredWaypointAnchorIds;
            debugger.RefreshRoute();

            if (debugger.LastRoute != null && debugger.LastRoute.Length > 1)
            {
                for (var i = 0; i < debugger.LastRoute.Length - 1; i++)
                {
                    RouteDebugSegment(routeObject.transform, "DebugRoute_Segment_" + i, debugger.LastRoute[i].WorldTarget, debugger.LastRoute[i + 1].WorldTarget, materialName);
                }
            }

            Label(routeObject.transform, "Route_Debug_Label", startAnchorId + "\n-> " + endAnchorId, labelPosition, 0.14f);
        }

        private static void RouteDebugSegment(Transform parent, string name, Vector3 start, Vector3 end, string materialName)
        {
            var delta = end - start;
            var flatDelta = new Vector3(delta.x, 0f, delta.z);
            var length = Mathf.Max(0.5f, flatDelta.magnitude);
            var midpoint = (start + end) * 0.5f;
            midpoint.y = Mathf.Max(start.y, end.y) + 0.08f;
            var segment = Cube(parent, name, midpoint, new Vector3(0.24f, 0.035f, length), materialName);
            if (flatDelta.sqrMagnitude > 0.001f)
            {
                segment.transform.localRotation = Quaternion.LookRotation(flatDelta.normalized, Vector3.up);
            }
        }

