        private static void WalkableRouteNode(Transform parent, string objectName, string anchorId, string displayName, string zoneId, Vector3 position, float yaw, string material, string[] connectedAnchorIds, bool isTransitNode, bool isUndergroundAccess, string hookId)
        {
            var node = new GameObject(objectName);
            node.transform.SetParent(parent, false);
            node.transform.position = position;
            node.transform.rotation = Quaternion.Euler(0f, yaw, 0f);

            var anchor = node.AddComponent<BubuTownNavigationAnchor>();
            anchor.AnchorId = anchorId;
            anchor.DisplayName = displayName;
            anchor.ZoneId = zoneId;
            anchor.Category = "RouteReadability";
            anchor.ConnectedAnchorIds = connectedAnchorIds;
            anchor.IsTransitNode = isTransitNode;
            anchor.IsUndergroundAccess = isUndergroundAccess;
            anchor.IsQuestRelevant = true;
            anchor.WorldTarget = position;

            Cube(node.transform, "Readable_Node_Ground_Disc", new Vector3(0f, 0.02f, 0f), new Vector3(2.15f, 0.07f, 2.15f), "MicroConcrete");
            Cube(node.transform, "Readable_Node_Color_Puck", new Vector3(0f, 0.09f, 0f), new Vector3(1.12f, 0.08f, 1.12f), material);
            Cube(node.transform, "Readable_Node_Glass_Pylon", new Vector3(0f, 1.12f, -0.42f), new Vector3(0.36f, 1.9f, 0.18f), "Glass");
            Cube(node.transform, "Readable_Node_Digital_Header", new Vector3(0f, 1.88f, -0.56f), new Vector3(1.38f, 0.24f, 0.055f), material);
            EmptyMarker(node.transform, hookId, new Vector3(0f, 0.35f, -0.95f));
            Label(node.transform, "Readable_Node_Label", displayName + "\n" + anchorId, new Vector3(0f, 2.35f, -0.64f), 0.1f);
        }

        private static void RouteArrowCluster(Transform parent, string name, Vector3 position, float yaw, string material)
        {
            var cluster = new GameObject(name);
            cluster.transform.SetParent(parent, false);
            cluster.transform.position = position;
            cluster.transform.rotation = Quaternion.Euler(0f, yaw, 0f);
            for (var i = 0; i < 3; i++)
            {
                Cube(cluster.transform, "Arrow_Center_Bar_" + i, new Vector3(0f, 0.03f, i * 0.72f), new Vector3(0.18f, 0.04f, 0.58f), material);
                Cube(cluster.transform, "Arrow_Left_Wing_" + i, new Vector3(-0.19f, 0.035f, 0.22f + i * 0.72f), new Vector3(0.36f, 0.04f, 0.12f), material).transform.localRotation = Quaternion.Euler(0f, -32f, 0f);
                Cube(cluster.transform, "Arrow_Right_Wing_" + i, new Vector3(0.19f, 0.035f, 0.22f + i * 0.72f), new Vector3(0.36f, 0.04f, 0.12f), material).transform.localRotation = Quaternion.Euler(0f, 32f, 0f);
            }
        }

        private static void BreadcrumbLine(Transform parent, string name, Vector3 position, Vector3 scale, string material, float yaw)
        {
            var line = Cube(parent, name, position, scale, material);
            line.transform.rotation = Quaternion.Euler(0f, yaw, 0f);
            for (var i = 0; i < 4; i++)
            {
                Cube(line.transform, "Breadcrumb_Dash_" + i, new Vector3(-0.38f + i * 0.26f, 1.18f, 0f), new Vector3(0.11f, 1.25f, 1.18f), i % 2 == 0 ? material : "CoolLight");
            }
        }

