        private static void CreatePhotoModeSystem(Transform root)
        {
            var group = Group(root, "14_Photo_Mode_System");
            var managerObject = new GameObject("Photo_Mode_Manager");
            managerObject.transform.SetParent(group, false);
            managerObject.transform.localPosition = new Vector3(-10f, 0.6f, -10f);
            var photoMode = managerObject.AddComponent<BubuTownPhotoMode>();
            var stateObject = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/08_Player_And_Runtime/GameState_Manager");
            if (stateObject != null)
            {
                photoMode.State = stateObject.GetComponent<BubuTownGameState>();
            }

            var spots = Group(group, "Photo_Spots");
            var plaza = PhotoSpot(spots, "PhotoSpot_Plaza_Fountain", new Vector3(0f, 1.1f, -14f), "广场喷泉机位");
            var home = PhotoSpot(spots, "PhotoSpot_Player_Home", new Vector3(-17f, 1.1f, -18f), "小屋门口机位");
            var park = PhotoSpot(spots, "PhotoSpot_Park_Picnic", new Vector3(35f, 1.1f, 25f), "公园野餐机位");
            photoMode.PhotoSpots = new[] { plaza, home, park };

            var interactionObject = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/08_Player_And_Runtime/Interaction_Manager");
            if (interactionObject != null)
            {
                var interaction = interactionObject.GetComponent<BubuTownInteractionSystem>();
                if (interaction != null)
                {
                    interaction.PhotoMode = photoMode;
                }
            }

            var hudObject = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/08_Player_And_Runtime/Runtime_HUD_Manager");
            if (hudObject != null)
            {
                var hud = hudObject.GetComponent<BubuTownRuntimeHud>();
                if (hud != null)
                {
                    hud.PhotoMode = photoMode;
                }
            }

            Label(group, "Photo_Mode_System_Label", "拍照模式系统\nP 开关 / [ ] 切换推荐机位", new Vector3(18f, 0.6f, 42f), 0.9f);
        }

