        private static void CreateSettingsSystem(Transform root)
        {
            var group = Group(root, "15_Settings_System");
            var managerObject = new GameObject("Settings_Manager");
            managerObject.transform.SetParent(group, false);
            managerObject.transform.localPosition = new Vector3(-12f, 0.6f, -10f);
            var settings = managerObject.AddComponent<BubuTownSettingsSystem>();

            var stateObject = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/08_Player_And_Runtime/GameState_Manager");
