            {
                settings.State = stateObject.GetComponent<BubuTownGameState>();
            }

            var playerObject = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/08_Player_And_Runtime/Player_Start_Bubu");
            if (playerObject != null)
            {
                settings.Player = playerObject.GetComponent<BubuTownPlayerController>();
            }

            var cameraObject = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/00_Lighting_And_Camera/Main Camera");
            if (cameraObject != null)
            {
                settings.CameraRig = cameraObject.GetComponent<BubuTownThirdPersonCamera>();
            }

            var hudObject = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/08_Player_And_Runtime/Runtime_HUD_Manager");
            if (hudObject != null)
            {
                var hud = hudObject.GetComponent<BubuTownRuntimeHud>();
                settings.Hud = hud;
                if (hud != null)
                {
                    hud.SettingsSystem = settings;
                }
            }

            var interactionObject = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/08_Player_And_Runtime/Interaction_Manager");
            if (interactionObject != null)
            {
                var interaction = interactionObject.GetComponent<BubuTownInteractionSystem>();
                if (interaction != null)
                {
                    interaction.SettingsSystem = settings;
                }
            }

            var toggles = Group(group, "Visible_Settings_Toggles");
            SettingToggle(toggles, "Setting_Camera_Sensitivity", "F1\n镜头灵敏度", new Vector3(-5f, 0.6f, 43f), "Blue");
            SettingToggle(toggles, "Setting_Fast_Run", "F2\n跑步速度", new Vector3(0f, 0.6f, 43f), "Green");
