        private static BubuTownHomeVisitorSpot HomeVisitorSpot(Transform parent, string objectName, string visitorName, Vector3 position, string material)
        {
            var holder = new GameObject(objectName);
            holder.transform.SetParent(parent, false);
            holder.transform.localPosition = position;
            Cylinder(holder.transform, "Visitor_Body_Preview", new Vector3(0f, 0.8f, 0f), new Vector3(0.55f, 1.6f, 0.55f), material);
            Sphere(holder.transform, "Visitor_Head_Preview", new Vector3(0f, 1.85f, 0f), new Vector3(0.58f, 0.58f, 0.58f), "Wall");

            var labelObject = new GameObject("Visitor_Status_Label", typeof(TextMesh));
            labelObject.transform.SetParent(holder.transform, false);
            labelObject.transform.localPosition = new Vector3(0f, 2.55f, 0f);
            labelObject.transform.localRotation = Quaternion.Euler(65f, 0f, 0f);
            var label = labelObject.GetComponent<TextMesh>();
            label.text = visitorName + "\n温馨度 20 后来访";
            label.anchor = TextAnchor.MiddleCenter;
            label.alignment = TextAlignment.Center;
            label.characterSize = 0.16f;
            label.fontSize = 48;
            label.color = new Color(0.12f, 0.10f, 0.08f);

            var spot = holder.AddComponent<BubuTownHomeVisitorSpot>();
            spot.VisitorName = visitorName;
            spot.RequiredWarmth = 20;
            spot.StatusLabel = label;
            spot.LockedMessage = "温馨度 20 后来访";
            spot.UnlockedMessage = "可以来小屋坐坐";
            spot.VisitMessage = "慢慢聊了一会儿，小屋有了朋友的声音。";
            AddInteractable(holder, BubuTownInteractableType.HomeVisitorSpot, objectName, visitorName + "来访点", "E: invite visitor when home warmth reaches 20");
            return spot;
        }

