        private static void LinkVisibleDoors()
        {
            var homeDoor = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/02_Buildings/Player_Rough_House/Door_Interactable");
            var homeSpawn = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/05_Player_Home_Interior/Home_Interior_Player_Spawn");
            if (homeDoor != null && homeSpawn != null)
            {
                var link = homeDoor.AddComponent<BubuTownDoorLink>();
                link.TargetPoint = homeSpawn.transform;
                link.MessageAfterUse = "进入布布的小屋：靠近装修网格按 E 打开装修模式。";
            }

            var exitDoor = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/05_Player_Home_Interior/Home_Interior_Exit_Door");
            if (exitDoor != null && homeDoor != null)
            {
                var link = exitDoor.AddComponent<BubuTownDoorLink>();
                link.TargetPoint = homeDoor.transform;
                link.TargetOffset = new Vector3(0f, 0f, -2.5f);
                link.MessageAfterUse = "离开小屋，回到小镇。";
            }

            var garageDoor = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Underground_Garage_Prototype_Reserved/Garage_Entry_Door_Interactable");
            var garageArrival = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Underground_Garage_Prototype_Reserved/B1_Parking_Level_Prototype/B1_Player_Arrival_Point");
            if (garageDoor != null && garageArrival != null)
            {
                var link = garageDoor.AddComponent<BubuTownDoorLink>();
                link.TargetPoint = garageArrival.transform;
                link.MessageAfterUse = "进入 B1 地下车库原型层：这里预留车辆、停车和电梯厅玩法。";
            }

            var garageExit = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Underground_Garage_Prototype_Reserved/B1_Parking_Level_Prototype/B1_Elevator_Exit_Door_Interactable");
            if (garageExit != null && garageDoor != null)
            {
                var link = garageExit.AddComponent<BubuTownDoorLink>();
                link.TargetPoint = garageDoor.transform;
                link.TargetOffset = new Vector3(0f, 0f, 2.8f);
                link.MessageAfterUse = "从 B1 电梯厅回到街面车库入口。";
            }

            var metroDoor = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Metro_Entrance_Plaza/Metro_Entry_Door_Interactable");
            var metroArrival = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Metro_Entrance_Plaza/Underground_Metro_Concourse_Prototype/Metro_Player_Arrival_Point");
            if (metroDoor != null && metroArrival != null)
            {
                var link = metroDoor.AddComponent<BubuTownDoorLink>();
                link.TargetPoint = metroArrival.transform;
                link.MessageAfterUse = "进入地下通勤连通厅：这里预留地铁、车库换乘和地下寻宝玩法。";
            }

            var metroExit = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Metro_Entrance_Plaza/Underground_Metro_Concourse_Prototype/Metro_Exit_To_Surface_Door_Interactable");
            if (metroExit != null && metroDoor != null)
            {
                var link = metroExit.AddComponent<BubuTownDoorLink>();
                link.TargetPoint = metroDoor.transform;
                link.TargetOffset = new Vector3(0f, 0f, -2.2f);
                link.MessageAfterUse = "从地下连通厅回到地铁入口广场。";
            }

            var metroGarageDoor = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Metro_Entrance_Plaza/Underground_Metro_Concourse_Prototype/Metro_Garage_Connector_Door_Interactable");
            var b1MetroArrival = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Underground_Garage_Prototype_Reserved/B1_Parking_Level_Prototype/B1_Metro_Connector_Arrival_Point");
            if (metroGarageDoor != null && b1MetroArrival != null)
            {
                var link = metroGarageDoor.AddComponent<BubuTownDoorLink>();
                link.TargetPoint = b1MetroArrival.transform;
                link.MessageAfterUse = "通过地下连通道来到 B1 车库换乘区。";
            }

            var b1MetroDoor = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Underground_Garage_Prototype_Reserved/B1_Parking_Level_Prototype/B1_Metro_Connector_Door_Interactable");
            var metroGarageArrival = GameObject.Find("BubuTown_Prototype_All_Visible_Before_Play/01_Map_Greybox/Metro_Entrance_Plaza/Underground_Metro_Concourse_Prototype/Metro_Garage_Connector_Arrival_Point");
            if (b1MetroDoor != null && metroGarageArrival != null)
            {
