        private static void MenuSubPanel(Transform parent, string panelName, string textName, string textValue, Vector2 anchoredPosition, Vector2 size)
        {
            var panel = UiPanel(parent, panelName, anchoredPosition, size, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Color(0.30f, 0.27f, 0.22f, 0.94f));
            UiText(panel.transform, textName, textValue, 20, TextAnchor.UpperLeft);
        }

        private static GameObject UiPanel(Transform parent, string name, Vector2 anchoredPosition, Vector2 size, Vector2 anchorMin, Vector2 anchorMax, Color color)
        {
            var panel = new GameObject(name, typeof(RectTransform), typeof(Image));
            panel.transform.SetParent(parent, false);
            var rect = panel.GetComponent<RectTransform>();
            rect.anchorMin = anchorMin;
            rect.anchorMax = anchorMax;
            rect.pivot = anchorMin;
            if (anchorMin == new Vector2(1f, 1f))
            {
                rect.pivot = new Vector2(1f, 1f);
            }
            else if (anchorMin == new Vector2(0.5f, 1f))
            {
                rect.pivot = new Vector2(0.5f, 1f);
            }
            else if (anchorMin == new Vector2(0.5f, 0f))
            {
                rect.pivot = new Vector2(0.5f, 0f);
            }
            rect.anchoredPosition = anchoredPosition;
            rect.sizeDelta = size;
            panel.GetComponent<Image>().color = color;
            return panel;
        }

        private static Text UiText(Transform parent, string name, string value, int fontSize, TextAnchor alignment)
        {
            var textObject = new GameObject(name, typeof(RectTransform), typeof(Text));
            textObject.transform.SetParent(parent, false);
            var rect = textObject.GetComponent<RectTransform>();
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.offsetMin = new Vector2(10f, 8f);
            rect.offsetMax = new Vector2(-10f, -8f);
            var text = textObject.GetComponent<Text>();
            text.text = value;
            text.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            text.fontSize = fontSize;
            text.alignment = alignment;
            text.color = Color.white;
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = 14;
            text.resizeTextMaxSize = fontSize;
            return text;
        }

        private static Text UiTextBox(Transform parent, string name, string value, int fontSize, TextAnchor alignment, Vector2 anchoredPosition, Vector2 size, Vector2 anchor)
        {
            var textObject = new GameObject(name, typeof(RectTransform), typeof(Text));
            textObject.transform.SetParent(parent, false);
            var rect = textObject.GetComponent<RectTransform>();
            rect.anchorMin = anchor;
            rect.anchorMax = anchor;
            rect.pivot = anchor;
            rect.anchoredPosition = anchoredPosition;
            rect.sizeDelta = size;
            var text = textObject.GetComponent<Text>();
            text.text = value;
            text.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            text.fontSize = fontSize;
            text.alignment = alignment;
            text.color = Color.white;
            text.resizeTextForBestFit = true;
            text.resizeTextMinSize = 14;
            text.resizeTextMaxSize = fontSize;
            return text;
        }

        private static Text FindUiText(string relativePath)
        {
            var go = FindSceneObject("BubuTown_Prototype_All_Visible_Before_Play/07_Minimal_UI_Reference/" + relativePath);
            return go != null ? go.GetComponent<Text>() : null;
        }

