                Cube(parent, "Retail_Front_Paving_South_" + i, new Vector3(offset, 0.18f, -34.7f), new Vector3(7.2f, 0.035f, 0.22f), i % 2 == 0 ? "Curb" : "Plaza");
            }
        }

        private static void CreatePavingGrid(Transform parent, string blockName, Vector3 center, Vector3 blockSize)
        {
            var minX = center.x - blockSize.x * 0.5f;
            var maxX = center.x + blockSize.x * 0.5f;
            var minZ = center.z - blockSize.z * 0.5f;
            var maxZ = center.z + blockSize.z * 0.5f;

            for (var x = Mathf.CeilToInt(minX / 4f) * 4f; x <= maxX; x += 4f)
            {
                Cube(parent, "Fine_Paving_" + blockName + "_X_" + x.ToString("F0"), new Vector3(x, center.y, center.z), new Vector3(0.055f, blockSize.y, blockSize.z), "TileGroove");
            }

            for (var z = Mathf.CeilToInt(minZ / 4f) * 4f; z <= maxZ; z += 4f)
            {
                Cube(parent, "Fine_Paving_" + blockName + "_Z_" + z.ToString("F0"), new Vector3(center.x, center.y, z), new Vector3(blockSize.x, blockSize.y, 0.055f), "TileGroove");
            }
        }

