        private static void CreateUndergroundGaragePrototype(Transform parent)
        {
            var garage = new GameObject("Underground_Garage_Prototype_Reserved");
            garage.transform.SetParent(parent, false);
            garage.transform.position = new Vector3(30f, 0f, -34f);
            garage.transform.rotation = Quaternion.Euler(0f, -8f, 0f);

            Cube(garage.transform, "Garage_Surface_Cutout_Dark_Opening", new Vector3(0f, 0.04f, 0f), new Vector3(13f, 0.08f, 9.5f), "ConcreteDark");
            var ramp = Cube(garage.transform, "Ramp_Deck_Downward_Visual", new Vector3(0f, -0.35f, -1.1f), new Vector3(8.2f, 0.16f, 11.5f), "Asphalt");
            ramp.transform.localRotation = Quaternion.Euler(7f, 0f, 0f);
            Cube(garage.transform, "Garage_Entrance_Header", new Vector3(0f, 2.25f, 4.4f), new Vector3(9.5f, 1.1f, 0.55f), "Metal");
            Cube(garage.transform, "Garage_Clearance_Sign", new Vector3(0f, 2.28f, 4.08f), new Vector3(4.2f, 0.42f, 0.08f), "Blue");
            Cube(garage.transform, "Garage_LED_Entry_Line", new Vector3(0f, 1.52f, 3.76f), new Vector3(8.4f, 0.12f, 0.08f), "Yellow");
            PointLight(garage.transform, "Garage_Entry_Soft_Ambience_Light", new Vector3(0f, 2.6f, 2.4f), 14f, 0.78f, new Color(1f, 0.82f, 0.52f));
            var entryTrigger = Cube(garage.transform, "Garage_Entry_Door_Interactable", new Vector3(0f, 1f, 3.1f), new Vector3(5.8f, 2f, 0.45f), "DarkGlass");
            entryTrigger.GetComponent<Renderer>().enabled = false;
            AddInteractable(entryTrigger, BubuTownInteractableType.Door, "GARAGE_ENTRY_DOOR", "地下车库入口", "E: enter B1 garage prototype");
            Cube(garage.transform, "Left_Retaining_Wall", new Vector3(-4.6f, 0.95f, -0.7f), new Vector3(0.32f, 1.9f, 10f), "Concrete");
            Cube(garage.transform, "Right_Retaining_Wall", new Vector3(4.6f, 0.95f, -0.7f), new Vector3(0.32f, 1.9f, 10f), "Concrete");
            Cube(garage.transform, "Entry_Barrier_Left", new Vector3(-1.8f, 0.85f, 3.2f), new Vector3(0.16f, 1.3f, 0.16f), "Metal");
            Cube(garage.transform, "Entry_Barrier_Arm", new Vector3(0.35f, 1.35f, 3.2f), new Vector3(4.3f, 0.12f, 0.12f), "Yellow");

            for (var i = 0; i < 4; i++)
            {
                var x = -3.15f + i * 2.1f;
                Cube(garage.transform, "Garage_Parking_Bay_Line_" + i, new Vector3(x, 0.15f, -5.3f), new Vector3(0.08f, 0.025f, 3.4f), "Crosswalk");
            }

            Cube(garage.transform, "Underground_Level_Preview_Slab", new Vector3(0f, -1.45f, -7.4f), new Vector3(10.5f, 0.16f, 4.2f), "ConcreteDark");
            Cube(garage.transform, "Ventilation_Core_A", new Vector3(-6.2f, 1.3f, 1.4f), new Vector3(1.2f, 2.6f, 1.2f), "Metal");
            Cube(garage.transform, "Ventilation_Core_A_Grille", new Vector3(-6.2f, 2.65f, 1.4f), new Vector3(1.4f, 0.18f, 1.4f), "DarkGlass");
            Cube(garage.transform, "Emergency_Stair_Glass_Box", new Vector3(6.4f, 1.7f, -2.4f), new Vector3(1.8f, 3.4f, 2.2f), "Glass");
            Cube(garage.transform, "Emergency_Stair_Door", new Vector3(6.4f, 0.95f, -3.55f), new Vector3(0.95f, 1.8f, 0.1f), "Blue");

            CreateB1GarageLevel(garage.transform);
            Label(garage.transform, "Garage_Close_Label", "地下车库入口\n后续车辆/地下层预留", new Vector3(0f, 3.15f, 4.05f), 0.22f);
        }

        private static void CreateB1GarageLevel(Transform garage)
        {
            var level = new GameObject("B1_Parking_Level_Prototype");
            level.transform.SetParent(garage, false);
            level.transform.localPosition = new Vector3(0f, -4.2f, -11.2f);

            Cube(level.transform, "B1_Floor_Slab_32x24", new Vector3(0f, 0f, 0f), new Vector3(32f, 0.18f, 24f), "ConcreteDark");
            Cube(level.transform, "B1_Back_Wall", new Vector3(0f, 1.8f, 12f), new Vector3(32f, 3.6f, 0.28f), "Concrete");
            Cube(level.transform, "B1_Left_Wall", new Vector3(-16f, 1.8f, 0f), new Vector3(0.28f, 3.6f, 24f), "Concrete");
            Cube(level.transform, "B1_Right_Wall", new Vector3(16f, 1.8f, 0f), new Vector3(0.28f, 3.6f, 24f), "Concrete");
            Cube(level.transform, "B1_Ceiling_Service_Plane", new Vector3(0f, 3.65f, 0f), new Vector3(32f, 0.16f, 24f), "ConcreteDark");

            for (var x = -10f; x <= 10f; x += 10f)
            {
                for (var z = -7f; z <= 7f; z += 7f)
                {
                    Cube(level.transform, "B1_Structural_Column_" + x.ToString("F0") + "_" + z.ToString("F0"), new Vector3(x, 1.75f, z), new Vector3(0.9f, 3.5f, 0.9f), "Concrete");
                    Cube(level.transform, "B1_Column_Warning_Band_" + x.ToString("F0") + "_" + z.ToString("F0"), new Vector3(x, 1.15f, z - 0.48f), new Vector3(0.92f, 0.22f, 0.05f), "Yellow");
                }
            }

            for (var i = 0; i < 6; i++)
            {
                var x = -12.5f + i * 5f;
                ParkingBay(level.transform, "B1_Left_Parking_Bay_" + i, "A" + (i + 1).ToString("00"), new Vector3(x, 0.14f, -9.2f), 0f, i == 0 || i == 1, i == 5, i == 2, i == 4);
                ParkingBay(level.transform, "B1_Right_Parking_Bay_" + i, "B" + (i + 1).ToString("00"), new Vector3(x, 0.14f, 9.2f), 180f, i == 0, i == 5, i == 3, i == 1);
            }

            Cube(level.transform, "B1_Driving_Aisle_Center_Line", new Vector3(0f, 0.16f, 0f), new Vector3(26f, 0.025f, 0.14f), "Crosswalk");
            Cube(level.transform, "B1_Ramp_End_Apron", new Vector3(0f, 0.16f, -12.4f), new Vector3(9f, 0.03f, 1.8f), "Asphalt");
            Cube(level.transform, "B1_Ramp_Target_Marker", new Vector3(0f, 0.38f, -10.6f), new Vector3(2.4f, 0.42f, 0.18f), "Blue");
