            Cube(level.transform, "B1_Elevator_Door_A", new Vector3(11.9f, 1.05f, 6.05f), new Vector3(1.1f, 2f, 0.12f), "Metal");
            Cube(level.transform, "B1_Elevator_Door_B", new Vector3(13.25f, 1.05f, 6.05f), new Vector3(1.1f, 2f, 0.12f), "Metal");
            var elevatorExit = Cube(level.transform, "B1_Elevator_Exit_Door_Interactable", new Vector3(12.6f, 1.05f, 5.75f), new Vector3(3.2f, 2.1f, 0.38f), "DarkGlass");
            elevatorExit.GetComponent<Renderer>().enabled = false;
            AddInteractable(elevatorExit, BubuTownInteractableType.Door, "B1_ELEVATOR_EXIT_DOOR", "B1 电梯厅", "E: return to street");
            Cube(level.transform, "B1_Metro_Connector_Corridor_Frame", new Vector3(15.82f, 1.4f, 1.1f), new Vector3(0.12f, 2.8f, 3.6f), "ConcreteDark");
            Cube(level.transform, "B1_Metro_Connector_Light_Line", new Vector3(15.74f, 2.55f, 1.1f), new Vector3(0.05f, 0.08f, 2.9f), "CoolLight");
