            EmptyMarker(level.transform, "B1_Vehicle_Spawn_Point_A", new Vector3(-8f, 0.35f, -2.2f));
            EmptyMarker(level.transform, "B1_Vehicle_Spawn_Point_B", new Vector3(8f, 0.35f, 2.2f));
