            UndergroundRouteNode(level.transform, "B1_RouteNode_Elevator", "b1.elevator", "B1 Elevator Lobby", "garage_b1", new Vector3(12.8f, 0.32f, 6f), new[] { "b1.player_arrival" }, true, false, "Yellow");
            UndergroundRouteNode(level.transform, "B1_RouteNode_Metro_Connector", "b1.metro_connector", "B1 Metro Connector", "garage_b1", new Vector3(14.2f, 0.32f, 1.1f), new[] { "b1.player_arrival", "metro.garage_connector" }, true, true, "NeonCyan");
            UndergroundRouteNode(level.transform, "B1_RouteNode_Parking_Aisle", "b1.parking_aisle", "B1 Parking Aisle", "garage_b1", new Vector3(0f, 0.32f, 0f), new[] { "b1.player_arrival", "b1.service_room", "b1.valet" }, false, true, "Green");
            UndergroundRouteNode(level.transform, "B1_RouteNode_Service_Room", "b1.service_room", "B1 Service Room", "garage_b1", new Vector3(-11.3f, 0.32f, -0.2f), new[] { "b1.parking_aisle" }, false, true, "WarmLight");
            UndergroundRouteNode(level.transform, "B1_RouteNode_Valet_Handoff", "b1.valet", "B1 Valet Handoff", "garage_b1", new Vector3(4.6f, 0.32f, 7.1f), new[] { "b1.parking_aisle" }, false, true, "Pink");
        }

