        private static void CreateB1PedestrianSafetyAndWayfindingPass(Transform level)
        {
            var safety = new GameObject("B1_Pedestrian_Safety_And_Wayfinding_Pass");
            safety.transform.SetParent(level, false);

            var crossing = GarageSafetyNode(safety.transform, "B1_Elevator_Pedestrian_Crossing", new Vector3(8.4f, 0f, 4.8f), 0f, "b1.safety.crossing.elevator", "Crossing", "Elevator pedestrian crossing", "b1.elevator", false, true, "Blue");
            for (var i = 0; i < 7; i++)
            {
                Cube(crossing.transform, "Crossing_Stripe_" + i, new Vector3(-3.2f + i * 1.05f, 0.205f, 0f), new Vector3(0.58f, 0.03f, 2.15f), "Crosswalk");
            }
            Cube(crossing.transform, "Crossing_Cyan_Edge_Line_A", new Vector3(0f, 0.225f, -1.2f), new Vector3(5.8f, 0.02f, 0.045f), "Blue");
            Cube(crossing.transform, "Crossing_Cyan_Edge_Line_B", new Vector3(0f, 0.225f, 1.2f), new Vector3(5.8f, 0.02f, 0.045f), "Blue");
            EmptyMarker(crossing.transform, "Future_B1_Crossing_Tutorial_Hook", new Vector3(0f, 0.35f, -1.6f));

            var exit = GarageSafetyNode(safety.transform, "B1_Emergency_Exit_West", new Vector3(-15.72f, 0f, 8.9f), 90f, "b1.safety.exit.west", "EmergencyExit", "West emergency exit", "b1.service_room", true, true, "Green");
            Cube(exit.transform, "Emergency_Exit_Door_Slab", new Vector3(0f, 1.05f, 0f), new Vector3(0.12f, 2.1f, 1.35f), "Metal");
            Cube(exit.transform, "Emergency_Exit_Green_Header", new Vector3(-0.08f, 2.35f, 0f), new Vector3(0.06f, 0.34f, 1.62f), "Green");
