        private static GameObject GarageSafetyNode(Transform parent, string name, Vector3 position, float yaw, string safetyId, string safetyType, string displayName, string linkedRouteNodeId, bool emergencyCritical, bool questReady, string accent)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.localPosition = position;
            node.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);
            var marker = node.AddComponent<BubuTownGarageSafetyMarker>();
            marker.SafetyId = safetyId;
            marker.SafetyType = safetyType;
            marker.DisplayName = displayName;
            marker.LinkedRouteNodeId = linkedRouteNodeId;
            marker.IsEmergencyCritical = emergencyCritical;
            marker.QuestReady = questReady;
            Cube(node.transform, "Garage_Safety_Status_Puck", new Vector3(-0.72f, 0.26f, -0.58f), new Vector3(0.36f, 0.055f, 0.36f), accent);
            EmptyMarker(node.transform, "Future_Garage_Safety_Runtime_Hook", new Vector3(0f, 0.35f, -0.86f));
            return node;
        }

