        private static void CreateB1SystemsReadinessAndRuntimeHooksPass(Transform level)
        {
            var systems = new GameObject("B1_Systems_Readiness_And_Runtime_Hooks_Pass");
            systems.transform.SetParent(level, false);

            var matrix = Cube(systems.transform, "B1_Parking_State_Matrix_Node", new Vector3(-15.82f, 1.9f, -8.15f), new Vector3(0.08f, 2.25f, 4.8f), "DarkGlass");
            AddParkingServiceMarker(matrix, "b1.runtime.parking_state_matrix", "B1 parking state matrix node", "ParkingStateMatrix", "b1.parking_aisle", true, true);
            for (var row = 0; row < 2; row++)
            {
                for (var col = 0; col < 6; col++)
                {
                    var status = (row == 0 && (col == 0 || col == 1)) ? "CoolLight" : ((row == 1 && col == 5) ? "WarmLight" : ((col == 2 || col == 3) ? "Red" : "Green"));
                    Cube(matrix.transform, "ParkingState_Cell_" + row + "_" + col, new Vector3(-0.07f, 0.55f + row * 0.52f, -1.82f + col * 0.72f), new Vector3(0.045f, 0.22f, 0.42f), status);
                }
            }
            Cube(matrix.transform, "ParkingState_Header_Cyan", new Vector3(-0.08f, 1.62f, 0f), new Vector3(0.04f, 0.1f, 3.7f), "NeonCyan");
            EmptyMarker(matrix.transform, "Future_B1_Parking_State_SaveData_Hook", new Vector3(0.62f, -1.4f, -1.8f));
            EmptyMarker(matrix.transform, "Future_B1_Occupancy_UI_Runtime_Hook", new Vector3(0.62f, -1.4f, -0.6f));

            var path = GarageSafetyNode(systems.transform, "B1_Vehicle_Path_Spline_Readiness_Node", new Vector3(0f, 0f, -2.4f), 0f, "b1.system.vehicle_path_spline", "VehiclePathSpline", "B1 vehicle path spline readiness node", "b1.parking_aisle", false, true, "NeonCyan");
            var pathNodes = new[]
            {
                new Vector3(-8.6f, 0.24f, -3.1f),
                new Vector3(-3.8f, 0.24f, -1.1f),
                new Vector3(1.8f, 0.24f, 0.1f),
                new Vector3(7.2f, 0.24f, 2.1f),
                new Vector3(11.2f, 0.24f, 5.2f)
            };
            for (var i = 0; i < pathNodes.Length; i++)
            {
                Cube(path.transform, "B1VehiclePath_Debug_Node_" + i, pathNodes[i], new Vector3(0.42f, 0.045f, 0.42f), i % 2 == 0 ? "NeonCyan" : "WarmLight");
                EmptyMarker(path.transform, "Future_B1_Vehicle_Path_Waypoint_" + i, pathNodes[i] + new Vector3(0f, 0.22f, 0f));
                if (i > 0)
                {
                    var previous = pathNodes[i - 1];
                    var current = pathNodes[i];
                    var midpoint = (previous + current) * 0.5f;
                    var delta = current - previous;
                    var segment = Cube(path.transform, "B1VehiclePath_Debug_Segment_" + (i - 1), midpoint, new Vector3(0.16f, 0.025f, delta.magnitude), "NeonCyan");
                    segment.transform.localRotation = Quaternion.Euler(0f, Mathf.Atan2(delta.x, delta.z) * Mathf.Rad2Deg, 0f);
                }
            }
            EmptyMarker(path.transform, "Future_B1_Vehicle_AI_Controller_Hook", new Vector3(0f, 0.35f, -4.25f));
            EmptyMarker(path.transform, "Future_B1_NavMesh_Rebuild_Hook", new Vector3(1.45f, 0.35f, -4.25f));

            var board = Cube(systems.transform, "B1_Quest_Dispatch_Board_Node", new Vector3(15.82f, 1.85f, -5.65f), new Vector3(0.08f, 2.1f, 3.9f), "DarkGlass");
            AddParkingServiceMarker(board, "b1.runtime.quest_dispatch_board", "B1 quest dispatch board node", "QuestDispatch", "b1.service_room", true, true);
            Cube(board.transform, "DispatchBoard_LostItem_Task_Line", new Vector3(-0.07f, 0.62f, -1.15f), new Vector3(0.045f, 0.1f, 1.25f), "WarmLight");
            Cube(board.transform, "DispatchBoard_EVService_Task_Line", new Vector3(-0.07f, 0.28f, 0.25f), new Vector3(0.045f, 0.1f, 1.05f), "CoolLight");
            Cube(board.transform, "DispatchBoard_Valet_Task_Line", new Vector3(-0.07f, -0.06f, 1.38f), new Vector3(0.045f, 0.1f, 0.85f), "Green");
            AddInteractable(board, BubuTownInteractableType.QuestItem, "B1_QUEST_DISPATCH_BOARD", "B1 任务调度板", "E: inspect B1 quest dispatch");
            EmptyMarker(board.transform, "Future_B1_LostItem_Quest_Runtime_Hook", new Vector3(-0.62f, -1.28f, -1.15f));
            EmptyMarker(board.transform, "Future_B1_EVService_Quest_Runtime_Hook", new Vector3(-0.62f, -1.28f, 0.25f));
            EmptyMarker(board.transform, "Future_B1_Valet_Quest_Runtime_Hook", new Vector3(-0.62f, -1.28f, 1.38f));

            var boundary = Cube(systems.transform, "B1_Modular_Garage_Art_Boundary_Node", new Vector3(0f, 0.205f, 11.35f), new Vector3(27.2f, 0.035f, 0.36f), "Grid");
            Cube(boundary.transform, "B1_ArtBoundary_WallKit_Socket_Bar", new Vector3(-8.6f, 0.08f, 0f), new Vector3(4.2f, 0.035f, 0.08f), "ConcreteDark");
            Cube(boundary.transform, "B1_ArtBoundary_SignageKit_Socket_Bar", new Vector3(0f, 0.08f, 0f), new Vector3(4.2f, 0.035f, 0.08f), "WarmLight");
            Cube(boundary.transform, "B1_ArtBoundary_LightKit_Socket_Bar", new Vector3(8.6f, 0.08f, 0f), new Vector3(4.2f, 0.035f, 0.08f), "CoolLight");
            EmptyMarker(boundary.transform, "Future_B1_Wall_Module_Art_Swap_Hook", new Vector3(-8.6f, 0.35f, -0.55f));
            EmptyMarker(boundary.transform, "Future_B1_Signage_Module_Art_Swap_Hook", new Vector3(0f, 0.35f, -0.55f));
            EmptyMarker(boundary.transform, "Future_B1_Lighting_Module_Art_Swap_Hook", new Vector3(8.6f, 0.35f, -0.55f));

            EmptyMarker(systems.transform, "Future_B1_Runtime_System_Index", new Vector3(0f, 0.35f, -5.2f));
            EmptyMarker(systems.transform, "Future_B1_SaveLoad_State_Index", new Vector3(1.4f, 0.35f, -5.2f));
            EmptyMarker(systems.transform, "Future_B1_FreeAsset_Replacement_Index", new Vector3(2.8f, 0.35f, -5.2f));
            Label(systems.transform, "B1_Systems_Readiness_Label", "B1 systems readiness\nparking state / vehicle path / quest dispatch / art boundary", new Vector3(0f, 0.95f, -5.45f), 0.12f);
        }

        private static void ParkingBay(Transform parent, string name, string bayId, Vector3 position, float yaw, bool isEvCharging, bool isVisitorReserved, bool isOccupiedAtPrototypeStart, bool isQuestReady)
        {
            var bay = new GameObject(name);
            bay.transform.SetParent(parent, false);
            bay.transform.localPosition = position;
            bay.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);
            var marker = bay.AddComponent<BubuTownParkingBayMarker>();
            marker.BayId = bayId;
            marker.ZoneId = "garage_b1";
            marker.IsEvCharging = isEvCharging;
            marker.IsVisitorReserved = isVisitorReserved;
            marker.IsOccupiedAtPrototypeStart = isOccupiedAtPrototypeStart;
            marker.IsQuestReady = isQuestReady;
            Cube(bay.transform, "Bay_Back_Line", new Vector3(0f, 0f, -1.9f), new Vector3(4.2f, 0.025f, 0.08f), "Crosswalk");
            Cube(bay.transform, "Bay_Left_Line", new Vector3(-2.1f, 0f, 0f), new Vector3(0.08f, 0.025f, 3.8f), "Crosswalk");
            Cube(bay.transform, "Bay_Right_Line", new Vector3(2.1f, 0f, 0f), new Vector3(0.08f, 0.025f, 3.8f), "Crosswalk");
            Cube(bay.transform, "Wheel_Stop", new Vector3(0f, 0.16f, -1.15f), new Vector3(2.7f, 0.22f, 0.22f), "Concrete");
            marker.VehicleSpawnPoint = EmptyMarker(bay.transform, "Vehicle_Spawn_Point", new Vector3(0f, 0.35f, 0.2f));
            Cube(bay.transform, "Bay_Id_Panel_" + bayId, new Vector3(0f, 0.08f, -1.58f), new Vector3(1.15f, 0.035f, 0.42f), isEvCharging ? "CoolLight" : isVisitorReserved ? "WarmLight" : "Blue");
            if (isEvCharging)
            {
                Cube(bay.transform, "EV_Charging_Floor_Icon", new Vector3(-1.25f, 0.09f, 0.65f), new Vector3(0.62f, 0.035f, 0.82f), "CoolLight");
                Cube(bay.transform, "EV_Wall_Charger_Hook", new Vector3(-1.9f, 0.9f, -1.72f), new Vector3(0.36f, 1.05f, 0.12f), "CoolLight");
            }
            if (isVisitorReserved)
            {
                Cube(bay.transform, "Visitor_Reserved_Floor_Panel", new Vector3(1.25f, 0.09f, 0.65f), new Vector3(0.82f, 0.035f, 0.82f), "WarmLight");
            }
            if (isOccupiedAtPrototypeStart)
            {
                ParkedCar(bay.transform, "Prototype_Occupied_Parked_EV", new Vector3(0f, 0.02f, 0.3f), 0f, isEvCharging ? "Blue" : "Grey");
            }
            if (isQuestReady)
            {
                EmptyMarker(bay.transform, "Future_Parking_Quest_Hook", new Vector3(0f, 0.35f, 1.55f));
                Cube(bay.transform, "QuestReady_Status_Light", new Vector3(1.85f, 0.35f, -1.65f), new Vector3(0.22f, 0.22f, 0.22f), "Green");
            }
            Label(bay.transform, "Bay_Data_Label", "B1-" + bayId + "\n" + (isEvCharging ? "EV " : "") + (isVisitorReserved ? "Visitor " : "") + (isQuestReady ? "Quest" : "Parking"), new Vector3(0f, 0.72f, -1.65f), 0.12f);
        }

        private static Transform EmptyMarker(Transform parent, string name, Vector3 position)
        {
            var marker = new GameObject(name);
            marker.transform.SetParent(parent, false);
            marker.transform.localPosition = position;
            return marker.transform;
        }

        private static Light PointLight(Transform parent, string name, Vector3 localPosition, float range, float intensity, Color color)
        {
            var lightObject = new GameObject(name, typeof(Light));
            lightObject.transform.SetParent(parent, false);
            lightObject.transform.localPosition = localPosition;
            var light = lightObject.GetComponent<Light>();
            light.type = LightType.Point;
            light.range = range;
            light.intensity = intensity;
            light.color = color;
            return light;
        }

        private static void CreateUrbanTrafficHierarchy(Transform parent)
        {
            var traffic = new GameObject("Urban_Traffic_Hierarchy_And_Garage_Access");
            traffic.transform.SetParent(parent, false);

            Cube(traffic.transform, "Main_Avenue_Center_Median_North", new Vector3(0f, 0.2f, 24f), new Vector3(0.65f, 0.18f, 24f), "ConcreteDark");
            Cube(traffic.transform, "Main_Avenue_Center_Median_South", new Vector3(0f, 0.2f, -24f), new Vector3(0.65f, 0.18f, 24f), "ConcreteDark");
            Cube(traffic.transform, "East_West_Median_Left", new Vector3(-24f, 0.205f, 0f), new Vector3(24f, 0.16f, 0.55f), "ConcreteDark");
            Cube(traffic.transform, "East_West_Median_Right", new Vector3(24f, 0.205f, 0f), new Vector3(24f, 0.16f, 0.55f), "ConcreteDark");

            for (var i = 0; i < 6; i++)
            {
                var z = -38f + i * 7.5f;
                Cube(traffic.transform, "Garage_Access_Directional_Dash_" + i, new Vector3(24.6f, 0.17f, z), new Vector3(2.6f, 0.025f, 0.18f), "Crosswalk");
            }

            Cube(traffic.transform, "Garage_Access_Left_Turn_Arrow_Shaft", new Vector3(27f, 0.18f, -24f), new Vector3(0.38f, 0.025f, 4f), "Crosswalk");
            Cube(traffic.transform, "Garage_Access_Left_Turn_Arrow_Head", new Vector3(25.7f, 0.185f, -26f), new Vector3(2f, 0.025f, 0.7f), "Crosswalk");
            Cube(traffic.transform, "Taxi_Loop_Service_Lane", new Vector3(-22f, 0.155f, -10.2f), new Vector3(14f, 0.035f, 0.18f), "Yellow");
            Cube(traffic.transform, "Bus_Only_Service_Lane", new Vector3(-14f, 0.155f, -8.6f), new Vector3(13f, 0.035f, 0.18f), "Blue");

            for (var i = 0; i < 9; i++)
            {
                var x = -36f + i * 9f;
                Cube(traffic.transform, "Pedestrian_Safety_Rail_North_" + i, new Vector3(x, 0.72f, 6.75f), new Vector3(3.8f, 0.12f, 0.12f), "Metal");
                Cube(traffic.transform, "Pedestrian_Safety_Rail_South_" + i, new Vector3(x, 0.72f, -6.75f), new Vector3(3.8f, 0.12f, 0.12f), "Metal");
                Cylinder(traffic.transform, "Rail_Post_North_" + i, new Vector3(x - 1.8f, 0.42f, 6.75f), new Vector3(0.08f, 0.84f, 0.08f), "Metal");
                Cylinder(traffic.transform, "Rail_Post_South_" + i, new Vector3(x - 1.8f, 0.42f, -6.75f), new Vector3(0.08f, 0.84f, 0.08f), "Metal");
            }

            Cube(traffic.transform, "Garage_Wayfinding_Pillar", new Vector3(24.5f, 1.55f, -30.5f), new Vector3(0.8f, 3.1f, 0.8f), "ConcreteDark");
            Cube(traffic.transform, "Garage_Wayfinding_Lightbox", new Vector3(24.5f, 2.85f, -30.95f), new Vector3(1.6f, 0.78f, 0.12f), "Blue");
            CreateModernParkingArrivalServicePass(traffic.transform);
            CreateModernRoadMarkingAndFlowPass(traffic.transform);
            CreateModernIntersectionControlAndWayfindingPass(traffic.transform);
        }

        private static void CreateModernParkingArrivalServicePass(Transform parent)
