        private static GameObject RoadFlowNode(Transform parent, string name, Vector3 position, float yaw, string flowId, string flowType, string displayName, string linkedRouteNodeId, bool supportsVehiclePath, bool supportsPedestrianSafety, bool visibleOnMinimap, string accent)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.localPosition = position;
            node.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            var marker = node.AddComponent<BubuTownRoadFlowMarker>();
            marker.FlowId = flowId;
            marker.FlowType = flowType;
            marker.DisplayName = displayName;
            marker.LinkedRouteNodeId = linkedRouteNodeId;
            marker.SupportsVehiclePath = supportsVehiclePath;
            marker.SupportsPedestrianSafety = supportsPedestrianSafety;
            marker.VisibleOnMinimap = visibleOnMinimap;

            Cube(node.transform, "RoadFlow_Status_Puck", new Vector3(-1.35f, 0.245f, -0.82f), new Vector3(0.28f, 0.035f, 0.28f), accent);
            EmptyMarker(node.transform, "Future_Road_Flow_Runtime_Hook", new Vector3(0f, 0.35f, -0.95f));
            return node;
        }

        private static void AddParkingServiceMarker(GameObject target, string serviceId, string displayName, string serviceType, string linkedRouteNodeId, bool playerFacing, bool questReady)
        {
            var marker = target.AddComponent<BubuTownParkingServiceMarker>();
            marker.ServiceId = serviceId;
            marker.DisplayName = displayName;
            marker.ServiceType = serviceType;
            marker.LinkedRouteNodeId = linkedRouteNodeId;
            marker.IsPlayerFacing = playerFacing;
            marker.IsQuestReady = questReady;
        }

