                Cube(transit.transform, "Vehicle_Lane_Path_Dash_WestLoop_" + i, new Vector3(-3.8f, 0.185f, z), new Vector3(0.16f, 0.025f, 3.2f), "WarmLight");
            }

            for (var i = 0; i < 5; i++)
            {
                var x = -28f + i * 14f;
                Cube(transit.transform, "Bus_Lane_Stop_Guide_Dash_" + i, new Vector3(x, 0.19f, -7.55f), new Vector3(3.8f, 0.025f, 0.15f), "CoolLight");
            }

            var busStop = EmptyMarker(transit.transform, "BusPath_Stop_A", new Vector3(-16f, 0.35f, -7.4f));
