            var garageExit = EmptyMarker(transit.transform, "VehiclePath_B1_Exit_Target", new Vector3(30f, 0.35f, -31.5f));
            var taxiPickup = EmptyMarker(transit.transform, "TaxiPath_Plaza_Pickup", new Vector3(-22f, 0.35f, -10.2f));
            var taxiFurniture = EmptyMarker(transit.transform, "TaxiPath_Furniture_Stop", new Vector3(23f, 0.35f, -10.2f));
            var taxiPark = EmptyMarker(transit.transform, "TaxiPath_Park_Stop", new Vector3(32f, 0.35f, 10f));
            EmptyMarker(transit.transform, "LightRailPath_Station_Stop", new Vector3(13.5f, 8.55f, 35.5f));

            var busPath = CreateVehiclePath(transit.transform, "Bus_Loop_Path", "bus_loop", new[] { busStop, busPlaza, busSchool, busPark, busStop });
            var taxiPath = CreateVehiclePath(transit.transform, "Taxi_Loop_Path", "taxi_loop", new[] { taxiPickup, taxiFurniture, taxiPark, busPlaza, taxiPickup });
            var garagePath = CreateVehiclePath(transit.transform, "Garage_EV_Merge_Path", "garage_ev_merge", new[] { garageExit, garageMerge, taxiFurniture, garageMerge });
