        private static GameObject TransitEntrance(Transform parent, string name, Vector3 position, float yaw, string entranceId, string entranceType, string displayName, string linkedRouteNodeId, bool supportsAccessibility, bool supportsQuestHooks, bool replaceableArtSlot, string accent)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.position = position;
            node.transform.rotation = Quaternion.Euler(0f, yaw, 0f);

            var marker = node.AddComponent<BubuTownTransitEntranceMarker>();
            marker.EntranceId = entranceId;
            marker.EntranceType = entranceType;
            marker.DisplayName = displayName;
            marker.LinkedRouteNodeId = linkedRouteNodeId;
            marker.SupportsAccessibility = supportsAccessibility;
            marker.SupportsQuestHooks = supportsQuestHooks;
            marker.ReplaceableArtSlot = replaceableArtSlot;

            Cube(node.transform, "TransitEntrance_Status_Puck", new Vector3(-1.15f, 0.245f, -0.96f), new Vector3(0.3f, 0.04f, 0.3f), accent);
            EmptyMarker(node.transform, "Future_Transit_Entrance_Art_Swap_Hook", new Vector3(1.15f, 0.35f, -1.1f));
            return node;
        }

        private static BubuTownVehiclePath CreateVehiclePath(Transform parent, string name, string pathId, Transform[] waypoints)
        {
            var pathObject = new GameObject(name);
            pathObject.transform.SetParent(parent, false);
            var path = pathObject.AddComponent<BubuTownVehiclePath>();
            path.PathId = pathId;
            path.Loop = true;
            path.Waypoints = waypoints;
            return path;
        }

        private static void AttachVehicleMover(GameObject vehicle, BubuTownVehiclePath path, float speed)
        {
            var mover = vehicle.AddComponent<BubuTownVehicleMover>();
            mover.Path = path;
            mover.SpeedMetersPerSecond = speed;
            mover.TurnSpeedDegrees = 150f;
            mover.MoveOnPlay = true;
        }

