            var garageQueue = ModernVehicleNode(polish.transform, "Garage_Ramp_Premium_EV_Queue", new Vector3(29.8f, 0f, -28.4f), -8f, "vehicle.garage.premium_ev_queue", "PremiumEVQueue", "Garage ramp premium EV queue", "Future_Garage_Parking_Tutorial_Hook", true, true, true, "NeonCyan");
