        private static GameObject ModernVehicleNode(Transform parent, string name, Vector3 position, float yaw, string vehicleId, string vehicleType, string displayName, string hookId, bool supportsVehiclePath, bool supportsGarageGameplay, bool replaceableModelSlot, string accent)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.position = position;
            node.transform.rotation = Quaternion.Euler(0f, yaw, 0f);

            var marker = node.AddComponent<BubuTownModernVehicleMarker>();
            marker.VehicleId = vehicleId;
            marker.VehicleType = vehicleType;
            marker.DisplayName = displayName;
            marker.LinkedRouteOrQuestId = hookId;
            marker.SupportsVehiclePath = supportsVehiclePath;
            marker.SupportsGarageGameplay = supportsGarageGameplay;
            marker.ReplaceableModelSlot = replaceableModelSlot;

            Cube(node.transform, "Vehicle_Node_Service_Pad", new Vector3(0f, 0.16f, 0f), new Vector3(3.6f, 0.08f, 1.42f), "MicroConcrete");
            Cube(node.transform, "Vehicle_Node_Status_Pin", new Vector3(-1.55f, 0.245f, -0.6f), new Vector3(0.28f, 0.035f, 0.28f), accent);
            EmptyMarker(node.transform, hookId, new Vector3(0f, 0.35f, -0.86f));
            EmptyMarker(node.transform, "Future_Vehicle_Model_Art_Swap_Hook", new Vector3(1.45f, 0.35f, -0.86f));
            return node;
        }

