        private static GameObject CityServiceNode(Transform parent, string name, Vector3 position, float yaw, string serviceId, string serviceType, string displayName, string hookId, bool supportsInteraction, bool visibleOnMap, bool replaceableArtSlot)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.position = position;
            node.transform.rotation = Quaternion.Euler(0f, yaw, 0f);

            var marker = node.AddComponent<BubuTownCityServiceMarker>();
            marker.ServiceId = serviceId;
            marker.ServiceType = serviceType;
            marker.DisplayName = displayName;
            marker.LinkedQuestHookId = hookId;
            marker.SupportsInteraction = supportsInteraction;
            marker.VisibleOnCityMap = visibleOnMap;
            marker.ReplaceableArtSlot = replaceableArtSlot;

            Cube(node.transform, "Service_Foundation_Slab", new Vector3(0f, 0.16f, 0f), new Vector3(3.25f, 0.1f, 1.15f), "MicroConcrete");
            Cube(node.transform, "Service_Cyan_Status_Dot", new Vector3(-1.35f, 0.25f, -0.48f), new Vector3(0.28f, 0.035f, 0.28f), "CoolLight");
            EmptyMarker(node.transform, hookId, new Vector3(0f, 0.35f, -0.72f));
            EmptyMarker(node.transform, "Future_Service_Art_Swap_Hook", new Vector3(1.35f, 0.35f, -0.72f));
            return node;
        }

