        private static GameObject PlayerEyeDeviceNode(Transform parent, string name, Vector3 position, float yaw, string deviceId, string deviceType, string displayName, string hookId, bool requiresMaintenance, bool visibleOnMap, string accent)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.position = position;
            node.transform.rotation = Quaternion.Euler(0f, yaw, 0f);

            var marker = node.AddComponent<BubuTownCityDeviceMarker>();
            marker.DeviceId = deviceId;
            marker.DeviceType = deviceType;
            marker.DisplayName = displayName;
            marker.LinkedQuestHookId = hookId;
            marker.RequiresMaintenance = requiresMaintenance;
            marker.VisibleOnCityMap = visibleOnMap;

            Cube(node.transform, "PlayerEye_Device_Status_Puck", new Vector3(-2.65f, 0.255f, -0.92f), new Vector3(0.3f, 0.045f, 0.3f), accent);
            EmptyMarker(node.transform, hookId, new Vector3(0f, 0.35f, -1.05f));
            EmptyMarker(node.transform, "Future_PlayerEye_Device_Art_Swap_Hook", new Vector3(1.25f, 0.35f, -1.05f));
            return node;
        }

