            Cube(garagePreview.transform, "Epoxy_Ramp_Cyan_Safety_Edge_Right", new Vector3(3.65f, 0.145f, -1.2f), new Vector3(0.1f, 0.018f, 8.8f), "CoolLight");

            Cube(surfaces.transform, "Street_Level_Texture_Audit_Pillar", new Vector3(-42.5f, 1.2f, 42.5f), new Vector3(1.0f, 2.4f, 0.2f), "MicroConcrete");
