        private static void Building(Transform parent, string name, Vector3 position, Vector3 size, string material, string label, string id, string prompt)
        {
            var holder = new GameObject(name);
            holder.transform.SetParent(parent, false);
            holder.transform.position = position;
            Cube(holder.transform, "Body", new Vector3(0f, size.y * 0.5f, 0f), size, "Concrete");
            Cube(holder.transform, "Ground_Floor_Storefront_Glass", new Vector3(0f, 2.05f, -size.z * 0.5f - 0.06f), new Vector3(size.x * 0.78f, 3.1f, 0.12f), "Glass");
            Cube(holder.transform, "Roof", new Vector3(0f, size.y + 0.2f, 0f), new Vector3(size.x + 0.8f, 0.35f, size.z + 0.8f), "ConcreteDark");
            Cube(holder.transform, "Parapet_Front", new Vector3(0f, size.y + 0.72f, -size.z * 0.5f), new Vector3(size.x + 1.1f, 0.7f, 0.35f), material);
            var door = Cube(holder.transform, "Door_Interactable", new Vector3(0f, 1.15f, -size.z * 0.5f - 0.13f), new Vector3(1.7f, 2.3f, 0.18f), "DarkGlass");
            Cube(holder.transform, "Sign_Backlit_Panel", new Vector3(0f, 4.25f, -size.z * 0.5f - 0.16f), new Vector3(size.x * 0.64f, 0.85f, 0.12f), material);
            Cube(holder.transform, "Entrance_Canopy", new Vector3(0f, 3.05f, -size.z * 0.5f - 0.85f), new Vector3(size.x * 0.5f, 0.18f, 1.45f), "Metal");
            Cube(holder.transform, "Entry_Step_01", new Vector3(0f, 0.16f, -size.z * 0.5f - 0.9f), new Vector3(3.2f, 0.24f, 0.9f), "ConcreteDark");
            Cube(holder.transform, "Entry_Step_02", new Vector3(0f, 0.34f, -size.z * 0.5f - 0.45f), new Vector3(2.5f, 0.2f, 0.65f), "Concrete");
            AddWindowGrid(holder.transform, size);
            AddSideWindowGrid(holder.transform, size);
            AddFacadeBands(holder.transform, size, material);
            AddStorefrontFrames(holder.transform, size);
            AddBalconyRows(holder.transform, size, material);
            AddFacadeAccessories(holder.transform, size);
            AddCornerColumns(holder.transform, size, "Metal");
            AddModernCoreBuildingDetails(holder.transform, name, size, material);
            AddInteractable(holder, name == "Furniture_Store" ? BubuTownInteractableType.Shop : BubuTownInteractableType.Door, id, label, prompt);
            AddInteractable(door, BubuTownInteractableType.Door, id + "_DOOR", label + "入口", prompt);
            Label(holder.transform, "Label_" + name, label, new Vector3(0f, 5.15f, -size.z * 0.58f), 0.42f);
        }

        private static void AddModernCoreBuildingDetails(Transform parent, string buildingName, Vector3 size, string accent)
        {
            Cube(parent, "Modern_Podium_Base", new Vector3(0f, 2.35f, -size.z * 0.5f - 0.36f), new Vector3(size.x + 1.2f, 4.4f, 0.42f), "DarkGlass");
            Cube(parent, "Upper_Volume_Stepback", new Vector3(size.x * 0.12f, size.y * 0.72f, 0.55f), new Vector3(size.x * 0.72f, Mathf.Max(3.2f, size.y * 0.42f), size.z * 0.72f), "ConcreteDark");
            Cube(parent, "Glass_Corner_Atrium_Left", new Vector3(-size.x * 0.5f - 0.18f, 3.35f, -size.z * 0.25f), new Vector3(0.24f, 5.6f, size.z * 0.42f), "Glass");
            Cube(parent, "Glass_Corner_Atrium_Right", new Vector3(size.x * 0.5f + 0.18f, 3.35f, -size.z * 0.25f), new Vector3(0.24f, 5.6f, size.z * 0.42f), "Glass");
            Cube(parent, "Street_Level_Lit_Soffit", new Vector3(0f, 3.85f, -size.z * 0.5f - 1.05f), new Vector3(size.x * 0.86f, 0.12f, 1.65f), "Yellow");
            Cube(parent, "Recessed_Entry_Mat", new Vector3(0f, 0.2f, -size.z * 0.5f - 1.55f), new Vector3(3.4f, 0.05f, 1.1f), accent);
            Cube(parent, "LED_Media_Wall", new Vector3(-size.x * 0.34f, 6.2f, -size.z * 0.5f - 0.28f), new Vector3(size.x * 0.22f, 2.6f, 0.09f), "Blue");
            Cube(parent, "LED_Media_Wall_Accent", new Vector3(-size.x * 0.34f, 6.2f, -size.z * 0.5f - 0.34f), new Vector3(size.x * 0.18f, 1.9f, 0.045f), accent);
            Cube(parent, "Vertical_Light_Strip_Left", new Vector3(-size.x * 0.5f - 0.18f, size.y * 0.48f, -size.z * 0.5f - 0.2f), new Vector3(0.08f, size.y * 0.72f, 0.08f), "Yellow");
            Cube(parent, "Vertical_Light_Strip_Right", new Vector3(size.x * 0.5f + 0.18f, size.y * 0.48f, -size.z * 0.5f - 0.2f), new Vector3(0.08f, size.y * 0.72f, 0.08f), "Yellow");
            Cube(parent, "Rooftop_Glass_Crown", new Vector3(0f, size.y + 1.55f, -size.z * 0.08f), new Vector3(size.x * 0.68f, 1.25f, size.z * 0.44f), "DarkGlass");

            var slabCount = Mathf.Max(3, Mathf.FloorToInt(size.y / 3.2f));
            for (var i = 1; i < slabCount; i++)
            {
                var y = 3.4f + i * ((size.y - 3.8f) / slabCount);
                Cube(parent, "Expressed_Floor_Slab_" + i, new Vector3(0f, y, -size.z * 0.5f - 0.18f), new Vector3(size.x + 0.45f, 0.08f, 0.22f), "Metal");
            }

            for (var i = 0; i < 4; i++)
            {
                var x = -size.x * 0.36f + i * size.x * 0.24f;
                Cube(parent, "Podium_Glass_Mullion_" + i, new Vector3(x, 2.35f, -size.z * 0.5f - 0.62f), new Vector3(0.08f, 3.5f, 0.08f), "Metal");
            }

            if (buildingName == "School")
            {
                Cube(parent, "School_Glass_Learning_Atrium", new Vector3(-size.x * 0.28f, 5.2f, -size.z * 0.5f - 0.5f), new Vector3(size.x * 0.3f, 6.4f, 0.28f), "Glass");
                Cube(parent, "School_Roof_Court_Railing", new Vector3(0f, size.y + 0.95f, 0f), new Vector3(size.x * 0.82f, 0.34f, size.z * 0.82f), "Metal");
            }
            else if (buildingName == "Furniture_Store")
            {
                Cube(parent, "Furniture_Showroom_Tall_Glass", new Vector3(size.x * 0.24f, 3.4f, -size.z * 0.5f - 0.52f), new Vector3(size.x * 0.32f, 5.8f, 0.22f), "Glass");
                Cube(parent, "Furniture_Loading_Bay_Modern_Door", new Vector3(-size.x * 0.38f, 1.55f, size.z * 0.5f + 0.08f), new Vector3(2.4f, 2.5f, 0.18f), "Metal");
            }
            else if (buildingName == "Player_Rough_House")
            {
                Cube(parent, "Player_Home_Modern_Balcony_Terrace", new Vector3(0f, 5.4f, -size.z * 0.5f - 0.75f), new Vector3(size.x * 0.62f, 0.18f, 1.35f), "ConcreteDark");
                Cube(parent, "Player_Home_Balcony_Glass", new Vector3(0f, 5.85f, -size.z * 0.5f - 1.38f), new Vector3(size.x * 0.64f, 0.7f, 0.08f), "Glass");
            }
            else if (buildingName == "Residents_Block")
            {
                for (var floor = 0; floor < 4; floor++)
                {
                    var y = 6f + floor * 3.6f;
                    Cube(parent, "Condo_Shared_Balcony_Level_" + floor, new Vector3(0f, y, -size.z * 0.5f - 0.75f), new Vector3(size.x * 0.82f, 0.16f, 1.1f), "ConcreteDark");
                    Cube(parent, "Condo_Glass_Rail_Level_" + floor, new Vector3(0f, y + 0.42f, -size.z * 0.5f - 1.28f), new Vector3(size.x * 0.84f, 0.64f, 0.08f), "Glass");
                }
            }
        }

        private static void AddWindowGrid(Transform parent, Vector3 size)
        {
            var floors = Mathf.Max(2, Mathf.FloorToInt((size.y - 4f) / 2.2f));
            var columns = Mathf.Max(3, Mathf.FloorToInt(size.x / 2.4f));
            for (var floor = 0; floor < floors; floor++)
            {
                var y = 5.7f + floor * 2.05f;
                if (y > size.y - 0.8f)
                {
                    continue;
                }

                for (var col = 0; col < columns; col++)
                {
                    var x = -size.x * 0.5f + 1.25f + col * ((size.x - 2.5f) / Mathf.Max(1, columns - 1));
                    Cube(parent, "Front_Window_F" + floor + "_C" + col, new Vector3(x, y, -size.z * 0.5f - 0.08f), new Vector3(1.15f, 1.05f, 0.08f), "Glass");
                    if (floor % 2 == 0)
                    {
                        Cube(parent, "Rear_Window_F" + floor + "_C" + col, new Vector3(x, y, size.z * 0.5f + 0.08f), new Vector3(1.15f, 1.05f, 0.08f), "DarkGlass");
                    }
                }
            }
        }

        private static void AddSideWindowGrid(Transform parent, Vector3 size)
        {
            var floors = Mathf.Max(2, Mathf.FloorToInt((size.y - 4f) / 2.2f));
            var columns = Mathf.Max(2, Mathf.FloorToInt(size.z / 2.5f));
            for (var floor = 0; floor < floors; floor++)
            {
                var y = 5.7f + floor * 2.05f;
                if (y > size.y - 0.8f)
                {
                    continue;
                }

                for (var col = 0; col < columns; col++)
                {
                    var z = -size.z * 0.5f + 1.25f + col * ((size.z - 2.5f) / Mathf.Max(1, columns - 1));
                    Cube(parent, "Left_Window_F" + floor + "_C" + col, new Vector3(-size.x * 0.5f - 0.08f, y, z), new Vector3(0.08f, 0.95f, 1.1f), "DarkGlass");
