        private static void AddBalconyRows(Transform parent, Vector3 size, string material)
        {
            var columns = Mathf.Max(2, Mathf.FloorToInt(size.x / 4f));
            for (var floor = 0; floor < 3; floor++)
            {
                var y = 6.1f + floor * 3.9f;
                if (y > size.y - 1.1f)
                {
                    continue;
                }

                for (var col = 0; col < columns; col++)
                {
                    var x = -size.x * 0.35f + col * (size.x * 0.7f / Mathf.Max(1, columns - 1));
                    Cube(parent, "Balcony_F" + floor + "_C" + col, new Vector3(x, y - 0.65f, -size.z * 0.5f - 0.55f), new Vector3(1.6f, 0.15f, 0.8f), "ConcreteDark");
                    Cube(parent, "Balcony_Glass_Rail_F" + floor + "_C" + col, new Vector3(x, y - 0.25f, -size.z * 0.5f - 0.92f), new Vector3(1.65f, 0.65f, 0.08f), "Glass");
                    Cube(parent, "Balcony_Side_Rail_L_F" + floor + "_C" + col, new Vector3(x - 0.82f, y - 0.25f, -size.z * 0.5f - 0.55f), new Vector3(0.08f, 0.55f, 0.68f), material);
                    Cube(parent, "Balcony_Side_Rail_R_F" + floor + "_C" + col, new Vector3(x + 0.82f, y - 0.25f, -size.z * 0.5f - 0.55f), new Vector3(0.08f, 0.55f, 0.68f), material);
                }
            }
        }

