        private static void TrafficLight(Transform parent, string name, Vector3 position, float yaw, float phaseOffset)
        {
            var holder = new GameObject(name);
            holder.transform.SetParent(parent, false);
            holder.transform.localPosition = position;
            holder.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);
            Cylinder(holder.transform, "Pole", new Vector3(0f, 1.6f, 0f), new Vector3(0.105f, 3.2f, 0.105f), "Metal");
            Cube(holder.transform, "Signal_Box", new Vector3(0f, 3.1f, -0.2f), new Vector3(0.38f, 1.08f, 0.18f), "ConcreteDark");
            var red = Sphere(holder.transform, "Light_Red", new Vector3(0f, 3.41f, -0.31f), new Vector3(0.16f, 0.16f, 0.045f), "Red");
            var yellow = Sphere(holder.transform, "Light_Yellow", new Vector3(0f, 3.1f, -0.31f), new Vector3(0.16f, 0.16f, 0.045f), "Yellow");
            var green = Sphere(holder.transform, "Light_Green", new Vector3(0f, 2.79f, -0.31f), new Vector3(0.16f, 0.16f, 0.045f), "Green");
            var pedestrian = Cube(holder.transform, "Pedestrian_Walk_Panel", new Vector3(0.36f, 2.18f, -0.28f), new Vector3(0.24f, 0.42f, 0.055f), "CoolLight");
            var cycle = holder.AddComponent<BubuTownTrafficSignalCycle>();
            cycle.RedLight = red.GetComponent<Renderer>();
            cycle.YellowLight = yellow.GetComponent<Renderer>();
            cycle.GreenLight = green.GetComponent<Renderer>();
            cycle.PedestrianPanel = pedestrian.GetComponent<Renderer>();
            cycle.GreenSeconds = 5f;
            cycle.YellowSeconds = 1.5f;
            cycle.RedSeconds = 4f;
            cycle.PhaseOffsetSeconds = phaseOffset;
        }

