        private static GameObject MixedUseSpace(Transform parent, string name, Vector3 position, float yaw, string spaceId, string spaceType, string displayName, string linkedEntranceId, bool interior, bool questReady, string accent)
        {
            var space = new GameObject(name);
            space.transform.SetParent(parent, false);
            space.transform.position = position;
            space.transform.rotation = Quaternion.Euler(0f, yaw, 0f);
            var marker = space.AddComponent<BubuTownMixedUseSpaceMarker>();
            marker.SpaceId = spaceId;
            marker.SpaceType = spaceType;
            marker.DisplayName = displayName;
            marker.LinkedEntranceId = linkedEntranceId;
            marker.HasInteriorSilhouette = interior;
            marker.IsQuestReady = questReady;
            Cube(space.transform, "MixedUse_Space_Status_Puck", new Vector3(-0.85f, 0.28f, -0.45f), new Vector3(0.44f, 0.06f, 0.44f), accent);
            EmptyMarker(space.transform, "Future_MixedUse_Content_Swap_Hook", new Vector3(0f, 0.35f, -0.65f));
            return space;
        }

