        private static GameObject GroundFloorInterior(Transform parent, string name, Vector3 position, float yaw, string interiorId, string interiorType, string displayName, string linkedEntranceId, string hookId, bool visibleThroughGlass, bool supportsInteriorLoad, bool replaceablePrefabSlot, string accent)
        {
