        private static GameObject ServiceAlleyNode(Transform parent, string name, Vector3 position, float yaw, string alleyId, string alleyType, string displayName, string linkedBuildingId, string hookId, bool deliveryQuest, bool maintenanceQuest, bool sightlineClear, string accent)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.localPosition = position;
            node.transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

            var marker = node.AddComponent<BubuTownServiceAlleyMarker>();
            marker.AlleyId = alleyId;
            marker.AlleyType = alleyType;
            marker.DisplayName = displayName;
            marker.LinkedBuildingId = linkedBuildingId;
            marker.LinkedQuestHookId = hookId;
            marker.SupportsDeliveryQuest = deliveryQuest;
            marker.SupportsMaintenanceQuest = maintenanceQuest;
            marker.KeepPlayerSightlineClear = sightlineClear;

            Cube(node.transform, "ServiceAlley_Status_Puck", new Vector3(-1.35f, 0.25f, -0.82f), new Vector3(0.32f, 0.045f, 0.32f), accent);
            EmptyMarker(node.transform, hookId, new Vector3(0f, 0.35f, -1.2f));
            EmptyMarker(node.transform, "Future_Service_Alley_Art_Swap_Hook", new Vector3(1.35f, 0.35f, -1.2f));
            return node;
        }

