        private static GameObject RooftopOperationsNode(Transform parent, string name, Vector3 position, float yaw, string operationId, string operationType, string displayName, string linkedBuildingId, bool supportsMaintenanceQuest, bool replaceableArtSlot, string accent)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.position = position;
            node.transform.rotation = Quaternion.Euler(0f, yaw, 0f);
            var marker = node.AddComponent<BubuTownRooftopOperationsMarker>();
            marker.OperationId = operationId;
            marker.OperationType = operationType;
            marker.DisplayName = displayName;
            marker.LinkedBuildingId = linkedBuildingId;
            marker.SupportsMaintenanceQuest = supportsMaintenanceQuest;
            marker.ReplaceableArtSlot = replaceableArtSlot;
            Cube(node.transform, "Rooftop_Operation_Status_Puck", new Vector3(-0.68f, 0.2f, -0.55f), new Vector3(0.34f, 0.055f, 0.34f), accent);
            EmptyMarker(node.transform, "Future_Rooftop_Operation_Runtime_Hook", new Vector3(0f, 0.35f, -0.82f));
            return node;
        }

