        private static GameObject SecondLevelConnection(Transform parent, string name, Vector3 position, float yaw, string connectionId, string connectionType, string displayName, string linkedRouteOrQuestId, bool photoSpot, bool traversal, bool replaceableArtSlot, string accent)
        {
            var node = new GameObject(name);
            node.transform.SetParent(parent, false);
            node.transform.position = position;
            node.transform.rotation = Quaternion.Euler(0f, yaw, 0f);

            var marker = node.AddComponent<BubuTownSecondLevelConnectionMarker>();
            marker.ConnectionId = connectionId;
            marker.ConnectionType = connectionType;
            marker.DisplayName = displayName;
            marker.LinkedRouteOrQuestId = linkedRouteOrQuestId;
            marker.SupportsPhotoSpot = photoSpot;
            marker.SupportsTraversal = traversal;
            marker.ReplaceableArtSlot = replaceableArtSlot;

            Cube(node.transform, "SecondLevel_Status_Puck", new Vector3(-1.15f, 0.18f, -0.78f), new Vector3(0.32f, 0.055f, 0.32f), accent);
            EmptyMarker(node.transform, "Future_Second_Level_Runtime_Hook", new Vector3(0f, 0.35f, -1.05f));
            EmptyMarker(node.transform, "Future_Second_Level_Art_Swap_Hook", new Vector3(1.15f, 0.35f, -1.05f));
            return node;
        }

