        private static GameObject FacadeUpgradeSlot(Transform parent, string name, Vector3 position, Vector3 size, float yaw, string slotId, string style, string assetType, int priority, bool needsInterior, bool streetCritical, string accent)
        {
            var slot = new GameObject(name);
            slot.transform.SetParent(parent, false);
            slot.transform.position = position;
            slot.transform.rotation = Quaternion.Euler(0f, yaw, 0f);

            var marker = slot.AddComponent<BubuTownFacadeUpgradeMarker>();
            marker.SlotId = slotId;
            marker.TargetStyle = style;
            marker.PreferredAssetType = assetType;
            marker.ReplacementPriority = priority;
            marker.NeedsInteriorBehindGlass = needsInterior;
            marker.StreetLevelCritical = streetCritical;

            Cube(slot.transform, "Facade_Ghost_Glass_Backplate", new Vector3(0f, size.y * 0.5f, 0f), size, "Glass");
            Cube(slot.transform, "Facade_Upgrade_Top_Rail", new Vector3(0f, size.y + 0.08f, -0.08f), new Vector3(Mathf.Max(size.x, 0.16f) + 0.4f, 0.12f, Mathf.Max(size.z, 0.16f) + 0.16f), "Metal");
            Cube(slot.transform, "Facade_Upgrade_Bottom_Rail", new Vector3(0f, 1.05f, -0.08f), new Vector3(Mathf.Max(size.x, 0.16f) + 0.4f, 0.12f, Mathf.Max(size.z, 0.16f) + 0.16f), "Metal");

            var width = Mathf.Max(size.x, size.z);
            for (var i = 0; i < 7; i++)
            {
                var x = -width * 0.42f + i * width * 0.14f;
                Cube(slot.transform, "Facade_Depth_Fin_" + i, new Vector3(x, size.y * 0.5f, -0.16f), new Vector3(0.06f, size.y * 0.86f, 0.12f), i % 2 == 0 ? "Metal" : accent);
            }

            for (var i = 0; i < 5; i++)
            {
                var y = 2.4f + i * (size.y - 3.2f) / 4f;
                Cube(slot.transform, "Facade_Interior_Shadow_Band_" + i, new Vector3(0f, y, -0.18f), new Vector3(width * 0.86f, 0.08f, 0.055f), "DarkGlass");
            }

            Cube(slot.transform, "Facade_Replacement_Priority_Puck", new Vector3(-width * 0.46f, 0.42f, -0.22f), new Vector3(0.48f, 0.08f, 0.48f), accent);
            EmptyMarker(slot.transform, "Future_Facade_Prefab_Socket", new Vector3(0f, 0.35f, -0.55f));
            EmptyMarker(slot.transform, "Future_Interior_Behind_Glass_Socket", new Vector3(width * 0.22f, 0.35f, -0.55f));
            Label(slot.transform, "Facade_Upgrade_Slot_Label", slotId + "\npriority " + priority, new Vector3(0f, 0.85f, -0.72f), 0.1f);
            return slot;
        }

