        private static void ReplacementSlot(Transform parent, string name, Vector3 position, Vector3 footprint, string accent, string label, string[] sockets)
        {
            var slot = new GameObject(name);
            slot.transform.SetParent(parent, false);
            slot.transform.localPosition = position;
            Cube(slot.transform, "Slot_Footprint_Ghost", new Vector3(0f, 0.19f, 0f), footprint, "Grid");
            Cube(slot.transform, "Slot_Accent_Edge_North", new Vector3(0f, 0.245f, footprint.z * 0.5f), new Vector3(footprint.x, 0.035f, 0.08f), accent);
            Cube(slot.transform, "Slot_Accent_Edge_South", new Vector3(0f, 0.245f, -footprint.z * 0.5f), new Vector3(footprint.x, 0.035f, 0.08f), accent);
            Cube(slot.transform, "Slot_Accent_Edge_East", new Vector3(footprint.x * 0.5f, 0.245f, 0f), new Vector3(0.08f, 0.035f, footprint.z), accent);
            Cube(slot.transform, "Slot_Accent_Edge_West", new Vector3(-footprint.x * 0.5f, 0.245f, 0f), new Vector3(0.08f, 0.035f, footprint.z), accent);

            for (var i = 0; i < sockets.Length; i++)
            {
                var x = -footprint.x * 0.35f + i * (footprint.x * 0.7f / Mathf.Max(1, sockets.Length - 1));
                EmptyMarker(slot.transform, sockets[i], new Vector3(x, 0.35f, 0f));
                Cube(slot.transform, "Socket_Visible_Puck_" + i, new Vector3(x, 0.28f, 0f), new Vector3(0.58f, 0.06f, 0.58f), accent);
            }

            Label(slot.transform, "Replacement_Slot_Label", label, new Vector3(0f, 0.72f, -footprint.z * 0.5f - 0.65f), 0.11f);
        }

        private static void FacadeUnifier(Transform parent, string name, Vector3 position, Vector3 size, float yaw, string panelMaterial, string frameMaterial, int verticalBays, int horizontalBands)
        {
            var facade = new GameObject(name);
            facade.transform.SetParent(parent, false);
            facade.transform.position = position;
            facade.transform.rotation = Quaternion.Euler(0f, yaw, 0f);

            Cube(facade.transform, "Unified_Glass_Panel_Field", new Vector3(0f, size.y * 0.5f, 0f), size, panelMaterial);
            Cube(facade.transform, "Unified_Top_Cap", new Vector3(0f, size.y + 0.26f, 0f), new Vector3(Mathf.Max(size.x, 0.24f) + 0.35f, 0.28f, Mathf.Max(size.z, 0.24f) + 0.35f), frameMaterial);
            Cube(facade.transform, "Unified_Ground_Floor_Shadow_Base", new Vector3(0f, 1.1f, -0.08f), new Vector3(Mathf.Max(size.x, 0.24f), 2.2f, Mathf.Max(size.z, 0.24f)), "DarkGlass");

            var width = Mathf.Max(size.x, size.z);
            for (var i = 0; i <= verticalBays; i++)
            {
                var offset = -width * 0.5f + width * i / verticalBays;
                var local = size.x >= size.z ? new Vector3(offset, size.y * 0.5f, -0.15f) : new Vector3(-0.15f, size.y * 0.5f, offset);
                var scale = size.x >= size.z ? new Vector3(0.08f, size.y, 0.08f) : new Vector3(0.08f, size.y, 0.08f);
                Cube(facade.transform, "Vertical_Mullion_" + i, local, scale, frameMaterial);
            }

            for (var i = 1; i < horizontalBands; i++)
            {
                var y = size.y * i / horizontalBands;
                var scale = size.x >= size.z ? new Vector3(size.x + 0.1f, 0.07f, 0.08f) : new Vector3(0.08f, 0.07f, size.z + 0.1f);
                Cube(facade.transform, "Horizontal_Floor_Line_" + i, new Vector3(0f, y, -0.16f), scale, frameMaterial);
            }
        }

        private static void SkylinePodium(Transform parent, string name, Vector3 position, Vector3 size, string accent, float yaw, int bays)
