        private static void PremiumGlassTower(Transform parent, string name, Vector3 position, Vector3 size, string accent, int floors)
        {
            var holder = new GameObject(name);
            holder.transform.SetParent(parent, false);
            holder.transform.position = position;

            Cube(holder.transform, "Setback_Podium", new Vector3(0f, 2.2f, 0f), new Vector3(size.x + 2.2f, 4.4f, size.z + 2.6f), "ConcreteDark");
            Cube(holder.transform, "Main_Glass_Core", new Vector3(0f, size.y * 0.5f + 2.2f, 0f), size, "DarkGlass");
            Cube(holder.transform, "Offset_Glass_Wing", new Vector3(size.x * 0.28f, size.y * 0.42f + 5.2f, -size.z * 0.28f), new Vector3(size.x * 0.48f, size.y * 0.72f, size.z * 0.42f), "Glass");
            Cube(holder.transform, "Metal_Roof_Crown", new Vector3(0f, size.y + 5.2f, 0f), new Vector3(size.x + 0.9f, 1.6f, size.z + 0.9f), "Metal");
