            for (var i = 0; i <= floors; i++)
            {
                var y = 5.2f + i * (size.y / (floors + 1));
                Cube(holder.transform, "Horizontal_Floor_Line_Front_" + i, new Vector3(0f, y, -size.z * 0.515f), new Vector3(size.x * 0.92f, 0.08f, 0.08f), "Metal");
