            }

            for (var i = 0; i < 4; i++)
            {
                var x = -size.x * 0.38f + i * size.x * 0.25f;
                Cube(holder.transform, "Vertical_Mullion_Front_" + i, new Vector3(x, size.y * 0.5f + 3.6f, -size.z * 0.535f), new Vector3(0.08f, size.y * 0.84f, 0.08f), "Metal");
