            }

            Cube(holder.transform, "Ground_Floor_Lobby_Glass", new Vector3(0f, 2.1f, -size.z * 0.62f), new Vector3(size.x * 0.74f, 3.1f, 0.12f), "Glass");
            Cube(holder.transform, "Lobby_Canopy", new Vector3(0f, 3.8f, -size.z * 0.82f), new Vector3(size.x * 0.82f, 0.24f, 1.5f), accent);
            Cube(holder.transform, "Lobby_Light_Strip", new Vector3(0f, 3.55f, -size.z * 1.08f), new Vector3(size.x * 0.68f, 0.08f, 0.08f), "Yellow");
