                    Sphere(parent, "Leaf_Clump_" + i, new Vector3(Mathf.Cos(angle) * size.x * 0.23f, 0.16f + i * 0.012f, Mathf.Sin(angle) * size.z * 0.22f), new Vector3(0.42f, 0.14f, 0.28f), i % 2 == 0 ? "Green" : "Yellow");
