                Sphere(parent, "Cupcake_Topping", new Vector3(0.1f, 0.9f, -0.08f), new Vector3(0.15f, 0.12f, 0.15f), "Red");
            }
            else
            {
                Cube(parent, "Quest_Prop_Object", new Vector3(0f, size.y * 0.5f, 0f), size, material);
            }
