            else if (id.Contains("table"))
            {
                CreateDisplayTable(parent, "Furniture_Table_Model", Vector3.zero, material);
            }
            else if (id.Contains("chair"))
            {
                CreateDisplayChair(parent, "Furniture_Chair_Model", Vector3.zero, material);
            }
            else if (id.Contains("rug") || id.Contains("floor"))
            {
                Cube(parent, "Textile_Surface", new Vector3(0f, 0.22f, 0f), new Vector3(size.x, 0.08f, size.z), material);
                Cube(parent, "Textile_Border", new Vector3(0f, 0.28f, 0f), new Vector3(size.x * 0.86f, 0.04f, size.z * 0.74f), "Wall");
            }
            else if (id.Contains("lamp"))
            {
                Cylinder(parent, "Lamp_Stem", new Vector3(0f, 0.72f, 0f), new Vector3(0.1f, 1.1f, 0.1f), "Metal");
                Cylinder(parent, "Lamp_Shade", new Vector3(0f, 1.38f, 0f), new Vector3(0.52f, 0.42f, 0.52f), material);
                Sphere(parent, "Lamp_Bulb", new Vector3(0f, 1.16f, 0f), new Vector3(0.22f, 0.22f, 0.22f), "Yellow");
            }
            else if (id.Contains("bookcase"))
            {
                Cube(parent, "Bookcase_Frame", new Vector3(0f, size.y * 0.48f, 0f), size, "Wood");
                for (var i = 0; i < 3; i++)
                {
                    Cube(parent, "Bookcase_Shelf_" + i, new Vector3(0f, 0.55f + i * 0.72f, -size.z * 0.52f), new Vector3(size.x * 0.86f, 0.08f, 0.08f), "Yellow");
                    Cube(parent, "Book_Row_" + i, new Vector3(-0.28f + i * 0.25f, 0.78f + i * 0.72f, -size.z * 0.56f), new Vector3(0.48f, 0.28f, 0.08f), i % 2 == 0 ? "Blue" : "Pink");
                }
            }
            else if (id.Contains("cake"))
            {
                Cylinder(parent, "Decor_Cake_Base", new Vector3(0f, 0.42f, 0f), new Vector3(0.58f, 0.35f, 0.58f), "Yellow");
                Sphere(parent, "Decor_Cake_Cream", new Vector3(0f, 0.72f, 0f), new Vector3(0.54f, 0.25f, 0.54f), material);
            }
            else if (id.Contains("plant"))
            {
                Cylinder(parent, "Plant_Pot", new Vector3(0f, 0.38f, 0f), new Vector3(0.45f, 0.55f, 0.45f), "Wood");
                Sphere(parent, "Plant_Crown_A", new Vector3(-0.18f, 0.92f, 0f), new Vector3(0.42f, 0.42f, 0.42f), material);
                Sphere(parent, "Plant_Crown_B", new Vector3(0.18f, 1.02f, 0.1f), new Vector3(0.42f, 0.42f, 0.42f), "Green");
            }
            else
            {
                Cube(parent, "Furniture_Display_Object", new Vector3(0f, size.y * 0.5f, 0f), size, material);
            }
        }

        private static void CreateDisplayChair(Transform parent, string name, Vector3 position, string material)
        {
            var holder = new GameObject(name);
            holder.transform.SetParent(parent, false);
            holder.transform.localPosition = position;
            Cube(holder.transform, "Seat", new Vector3(0f, 0.55f, 0f), new Vector3(1f, 0.18f, 1f), material);
            Cube(holder.transform, "Back", new Vector3(0f, 1.15f, 0.42f), new Vector3(1f, 1.05f, 0.16f), material);
            for (var x = -0.36f; x <= 0.36f; x += 0.72f)
            {
                for (var z = -0.36f; z <= 0.36f; z += 0.72f)
                {
                    Cube(holder.transform, "Leg_" + x.ToString("F1") + "_" + z.ToString("F1"), new Vector3(x, 0.28f, z), new Vector3(0.14f, 0.56f, 0.14f), "Wood");
                }
            }
        }

        private static void CreateDisplayTable(Transform parent, string name, Vector3 position, string material)
        {
            var holder = new GameObject(name);
            holder.transform.SetParent(parent, false);
            holder.transform.localPosition = position;
            Cube(holder.transform, "Top", new Vector3(0f, 0.82f, 0f), new Vector3(1.75f, 0.18f, 1.25f), material);
            Cube(holder.transform, "Leg_Left_Front", new Vector3(-0.66f, 0.42f, -0.46f), new Vector3(0.16f, 0.82f, 0.16f), "Wood");
            Cube(holder.transform, "Leg_Right_Front", new Vector3(0.66f, 0.42f, -0.46f), new Vector3(0.16f, 0.82f, 0.16f), "Wood");
            Cube(holder.transform, "Leg_Left_Back", new Vector3(-0.66f, 0.42f, 0.46f), new Vector3(0.16f, 0.82f, 0.16f), "Wood");
            Cube(holder.transform, "Leg_Right_Back", new Vector3(0.66f, 0.42f, 0.46f), new Vector3(0.16f, 0.82f, 0.16f), "Wood");
        }

        private static void Npc(Transform parent, string objectName, string npcId, string npcName, string role, Vector3 position, string material, string[] quests, string dialogue)
        {
            var holder = new GameObject(objectName);
            holder.transform.SetParent(parent, false);
            holder.transform.position = position;
            holder.transform.localScale = Vector3.one * 0.86f;
            CreateLowPolyNpcVisual(holder.transform, npcId, material);
            var npc = holder.AddComponent<BubuTownNpc>();
            npc.NpcId = npcId;
            npc.NpcName = npcName;
            npc.Role = role;
            npc.FriendshipLevel = 0;
            npc.FriendshipLabel = "陌生";
            npc.QuestIds = quests;
            npc.DefaultDialogue = dialogue;
            npc.FriendshipDialogues = DialogueLevelsForNpc(npcId, dialogue);
            CreateNpcDialoguePlan(holder.transform, npc.NpcName, npc.FriendshipDialogues);
            AddSkinSlot(holder, npcId, false);
            AddInteractable(holder, BubuTownInteractableType.Npc, npcId, npcName, "E: talk / accept quest");
            Label(holder.transform, "Nameplate", npcName + "\n好感 0: 陌生", new Vector3(0f, 3.25f, 0f), 0.32f);
        }

        private static void CreateNpcDialoguePlan(Transform parent, string npcName, string[] dialogues)
        {
            var group = new GameObject("Friendship_Dialogue_Plan");
            group.transform.SetParent(parent, false);
            group.transform.localPosition = new Vector3(1.4f, 0f, 0f);
            Label(group.transform, "Dialogue_Plan_Title", npcName + "\n好感对白 0-3", new Vector3(0f, 2.65f, 0f), 0.18f);
            for (var i = 0; i < dialogues.Length; i++)
            {
                Label(group.transform, "Dialogue_Level_" + i, "L" + i + ": " + dialogues[i], new Vector3(0f, 2.25f - i * 0.35f, 0f), 0.12f);
            }
        }

        private static string[] DialogueLevelsForNpc(string npcId, string fallback)
        {
            switch (npcId)
            {
                case "npc_manager":
                    return new[]
                    {
                        "欢迎来到小镇。先从广场开始，慢慢认识大家吧。",
                        "你已经记住几条路了吧？小镇不大，但每条路都有事情发生。",
                        "今天也辛苦啦。看到广场越来越干净，我就知道你在用心生活。",
                        "布布，这里已经很像你的家了。以后有新活动，我会先告诉你。"
                    };
                case "npc_cake_owner":
                    return new[]
                    {
                        "今天有点忙，可以帮我把小蛋糕送出去吗？",
                        "你来得正好，刚出炉的小蛋糕闻起来会让人心情变软。",
                        "我给你留了一块边角料蛋糕，不卖，只给熟人尝。",
                        "下次我们一起设计一款布布小屋主题蛋糕吧。"
                    };
                case "npc_teacher":
                    return new[]
                    {
                        "有个孩子的铅笔盒不见了，我们一起找找。",
                        "你观察东西很仔细，适合帮孩子们做课后小测验。",
                        "孩子们已经开始问：布布今天会不会来学校玩？",
                        "教室窗边的位置给你留着，想安静看书随时来。"
                    };
                case "npc_furniture_owner":
                    return new[]
                    {
                        "小屋空空的？来挑第一件家具吧。",
                        "小椅子虽然小，但摆对位置，房间马上就有生活感。",
                        "我进了一些更温暖的木色家具，感觉很适合你的小屋。",
                        "以后有稀有家具样品，我第一个叫你来试摆。"
                    };
                case "npc_child":
                    return new[]
                    {
                        "我刚刚在公园和广场都玩过。",
                        "你找到东西好厉害。下次寻宝我还想和你一队。",
                        "我画了一张小镇藏宝图，不过有一半是我想象的。",
                        "你的小屋变温馨后，我可以去坐坐吗？我会带贴纸。"
                    };
                default:
                    return new[] { fallback, fallback, fallback, fallback };
            }
        }

        private static void AddSkinSlot(GameObject character, string characterId, bool allowPrivate)
        {
            var original = new GameObject("PublicOriginal");
            original.transform.SetParent(character.transform, false);
            original.transform.localPosition = Vector3.zero;

            var localPrivate = new GameObject("LocalPrivateSkinMount_DoNotCommit");
            localPrivate.transform.SetParent(character.transform, false);
            localPrivate.transform.localPosition = Vector3.zero;

            var slot = character.AddComponent<BubuTownSkinSlot>();
            slot.CharacterId = characterId;
            slot.PublicOriginalRoot = original.transform;
            slot.LocalPrivateSkinMount = localPrivate.transform;
            slot.AllowLocalPrivateSkin = allowPrivate;
        }

        private static void Quest(Transform parent, string objectName, string questId, string questName, string startsAt, string target, Vector3 position, int coins, int favor, bool priority)
        {
            var marker = Cube(parent, objectName, position + new Vector3(0f, 0.45f, 0f), new Vector3(1.2f, 0.9f, 1.2f), priority ? "Yellow" : "Blue");
            var quest = marker.AddComponent<BubuTownQuestMarker>();
            quest.QuestId = questId;
            quest.QuestName = questName;
            quest.StartsAt = startsAt;
            quest.Target = target;
            quest.CoinReward = coins;
            quest.FavorReward = favor;
            quest.PriorityForFirstPlayableLoop = priority;
            if (questId != "Q001")
            {
                AddInteractable(marker, BubuTownInteractableType.QuestItem, questId, questName, target);
            }

            var labelText = questId == "Q001" ? questId + "\n" + questName + "\n跟随 5 个地点标记" : questId + "\n" + questName;
            Label(marker.transform, "Quest_Label", labelText, new Vector3(0f, 1f, 0f), 0.24f);
        }

        private static void QuestProp(Transform parent, string objectName, string questId, string stepId, string displayName, string hint, int requiredSteps, Vector3 position, Vector3 size, string material)
        {
            QuestProp(parent, objectName, questId, stepId, displayName, hint, requiredSteps, position, size, material, string.Empty, string.Empty);
        }

        private static void QuestProp(Transform parent, string objectName, string questId, string stepId, string displayName, string hint, int requiredSteps, Vector3 position, Vector3 size, string material, string requiredCompletedStepId, string prerequisiteMissingMessage)
        {
            var prop = new GameObject(objectName);
            prop.transform.SetParent(parent, false);
            prop.transform.localPosition = position;
            var touch = Cube(prop.transform, "Interaction_Touch_Volume", Vector3.zero, size, material);
            touch.GetComponent<Renderer>().enabled = false;
            CreateQuestPropVisual(prop.transform, objectName, size, material);
            var step = prop.AddComponent<BubuTownQuestStepMarker>();
            step.QuestId = questId;
            step.StepId = stepId;
            step.StepName = displayName;
            step.StepHint = hint;
            step.RequiredCompletedStepId = requiredCompletedStepId;
            step.PrerequisiteMissingMessage = prerequisiteMissingMessage;
            step.RequiredStepsForQuest = requiredSteps;
            step.CompletesQuestOnInteract = true;
            AddInteractable(prop, BubuTownInteractableType.QuestItem, stepId, displayName, "E: " + hint);
            var prerequisiteLabel = string.IsNullOrEmpty(requiredCompletedStepId) ? string.Empty : "\n前置: " + requiredCompletedStepId;
            Label(prop.transform, "Step_Label", questId + "\n" + displayName + "\n步骤目标 " + requiredSteps + prerequisiteLabel, new Vector3(0f, size.y * 0.65f + 0.45f, 0f), 0.22f);
        }

        private static void Furniture(Transform parent, string objectName, string id, string displayName, int price, int warmth, int requiredWarmth, Vector3 position, Vector3 size, string material)
        {
            var go = new GameObject(objectName);
            go.transform.SetParent(parent, false);
            go.transform.localPosition = position;
            Cube(go.transform, "Showroom_Platform", new Vector3(0f, 0.08f, 0f), new Vector3(Mathf.Max(size.x + 0.5f, 1.8f), 0.16f, Mathf.Max(size.z + 0.5f, 1.8f)), "ConcreteDark");
            CreateFurnitureShowroomVisual(go.transform, id, size, material);
            Cylinder(go.transform, "Display_Spotlight", new Vector3(0f, Mathf.Max(1.2f, size.y + 0.65f), -Mathf.Max(0.55f, size.z * 0.42f)), new Vector3(0.18f, 0.18f, 0.18f), "Yellow");
            var touch = Cube(go.transform, "Interaction_Touch_Volume", new Vector3(0f, size.y * 0.5f, 0f), size + new Vector3(0.4f, 0.3f, 0.4f), material);
            touch.GetComponent<Renderer>().enabled = false;
            var furniture = go.AddComponent<BubuTownFurnitureMarker>();
            furniture.FurnitureId = id;
            furniture.FurnitureName = displayName;
            furniture.Price = price;
            furniture.WarmthValue = warmth;
            furniture.RequiredWarmth = requiredWarmth;
            var unlockText = requiredWarmth > 0 ? "requires warmth " + requiredWarmth : "available now";
            AddInteractable(go, BubuTownInteractableType.Furniture, id, displayName, "Shop item: " + price + " coins, warmth +" + warmth + ", " + unlockText);
            Label(go.transform, "Price_Label", displayName + "\n" + price + "币 / 温馨+" + warmth + "\n开放: " + requiredWarmth, new Vector3(0f, size.y * 0.75f + 0.8f, 0f), 0.24f);
        }

        private static Transform Group(Transform parent, string name)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            return go.transform;
        }

        private static GameObject Cube(Transform parent, string name, Vector3 position, Vector3 scale, string materialName)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
            go.name = name;
            go.transform.SetParent(parent, false);
            go.transform.localPosition = position;
            go.transform.localScale = scale;
            ApplyMaterial(go, materialName);
            return go;
        }

        private static GameObject Cylinder(Transform parent, string name, Vector3 position, Vector3 scale, string materialName)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
            go.name = name;
            go.transform.SetParent(parent, false);
            go.transform.localPosition = position;
            go.transform.localScale = scale;
            ApplyMaterial(go, materialName);
            return go;
        }

        private static GameObject Sphere(Transform parent, string name, Vector3 position, Vector3 scale, string materialName)
        {
            var go = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            go.name = name;
            go.transform.SetParent(parent, false);
            go.transform.localPosition = position;
            go.transform.localScale = scale;
            ApplyMaterial(go, materialName);
            return go;
        }

        private static BubuTownUndergroundRouteNode UndergroundRouteNode(
            Transform parent,
            string objectName,
            string nodeId,
            string displayName,
            string zoneId,
            Vector3 position,
            string[] connectedNodeIds,
            bool isTransferPoint,
            bool isQuestReady,
            string materialName)
        {
            var marker = Cube(parent, objectName, position, new Vector3(1.15f, 0.42f, 1.15f), materialName);
            var node = marker.AddComponent<BubuTownUndergroundRouteNode>();
            node.NodeId = nodeId;
            node.DisplayName = displayName;
            node.ZoneId = zoneId;
            node.ConnectedNodeIds = connectedNodeIds;
            node.IsTransferPoint = isTransferPoint;
            node.IsQuestReady = isQuestReady;
            Label(marker.transform, "Route_Node_Label", displayName + "\n" + nodeId, new Vector3(0f, 0.82f, 0f), 0.14f);
            return node;
        }

        private static void Label(Transform parent, string name, string text, Vector3 localPosition, float size)
        {
            var go = new GameObject(name, typeof(TextMesh));
            go.transform.SetParent(parent, false);
            go.transform.localPosition = localPosition;
            go.transform.localRotation = Quaternion.Euler(65f, 0f, 0f);
            var label = go.GetComponent<TextMesh>();
            label.text = text;
            label.anchor = TextAnchor.MiddleCenter;
            label.alignment = TextAlignment.Center;
            label.characterSize = size;
            label.fontSize = 48;
            label.color = new Color(0.12f, 0.10f, 0.08f);
            var renderer = go.GetComponent<Renderer>();
            if (renderer != null)
            {
                renderer.enabled = false;
            }
            var proximity = go.AddComponent<BubuTownProximityLabel>();
            proximity.VisibleDistance = Mathf.Clamp(size * 1.45f, 0.85f, 1.35f);
        }

        private static void AddInteractable(GameObject go, BubuTownInteractableType type, string id, string displayName, string prompt)
        {
            var interactable = go.GetComponent<BubuTownInteractable>() ?? go.AddComponent<BubuTownInteractable>();
            interactable.Type = type;
            interactable.Id = id;
            interactable.DisplayName = displayName;
            interactable.InteractionPrompt = prompt;
        }

