        private static void CreateMaterial(string name, Color color, string pattern, Vector2 tiling)
        {
            CreateMaterial(name, color);
            var material = AssetDatabase.LoadAssetAtPath<Material>(MaterialFolder + "/Bubu_" + name + ".mat");
            if (material == null)
            {
                return;
            }

            var texture = CreateGeneratedTexture(pattern);
            if (texture != null)
            {
                material.mainTexture = texture;
                material.mainTextureScale = tiling;
                EditorUtility.SetDirty(material);
            }
        }

        private static void CreateMaterial(string name, Color color)
        {
            var path = MaterialFolder + "/Bubu_" + name + ".mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (material == null)
            {
                material = new Material(FindProjectLitShader());
                AssetDatabase.CreateAsset(material, path);
            }
            material.shader = FindProjectLitShader();
            material.name = "Bubu_" + name;
            material.color = color;
            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", color);
            }
            if (material.HasProperty("_Color"))
            {
                material.SetColor("_Color", color);
            }
            if (color.a < 0.99f)
            {
                if (material.HasProperty("_Surface"))
                {
                    material.SetFloat("_Surface", 1f);
                    material.SetFloat("_Blend", 0f);
                    material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
                    material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                    material.SetInt("_ZWrite", 0);
                    material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
                }
                else
                {
                    material.SetFloat("_Mode", 3f);
                    material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
                    material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                    material.SetInt("_ZWrite", 0);
                    material.DisableKeyword("_ALPHATEST_ON");
                    material.EnableKeyword("_ALPHABLEND_ON");
                    material.DisableKeyword("_ALPHAPREMULTIPLY_ON");
                }
                material.renderQueue = 3000;
            }
            else
            {
                if (material.HasProperty("_Surface"))
                {
                    material.SetFloat("_Surface", 0f);
                    material.DisableKeyword("_SURFACE_TYPE_TRANSPARENT");
                }
                material.SetFloat("_Mode", 0f);
                material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.One);
                material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.Zero);
                material.SetInt("_ZWrite", 1);
                material.DisableKeyword("_ALPHATEST_ON");
                material.DisableKeyword("_ALPHABLEND_ON");
                material.DisableKeyword("_ALPHAPREMULTIPLY_ON");
                material.renderQueue = -1;
            }
            ConfigureModernMaterial(name, material);
            EditorUtility.SetDirty(material);
        }

        private static Shader FindProjectLitShader()
        {
            return Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Universal Render Pipeline/Simple Lit") ?? Shader.Find("Standard");
        }

        private static void ConfigureModernMaterial(string name, Material material)
        {
            SetMaterialFloat(material, "_Metallic", 0f);
            SetMaterialFloat(material, "_Smoothness", 0.25f);
            SetMaterialFloat(material, "_Glossiness", 0.25f);
            material.DisableKeyword("_EMISSION");
            SetMaterialColor(material, "_EmissionColor", Color.black);

            switch (name)
            {
                case "Glass":
                    SetMaterialFloat(material, "_Metallic", 0f);
                    SetMaterialFloat(material, "_Smoothness", 0.88f);
                    SetMaterialFloat(material, "_Glossiness", 0.88f);
                    material.EnableKeyword("_EMISSION");
                    SetMaterialColor(material, "_EmissionColor", new Color(0.05f, 0.22f, 0.34f));
                    break;
                case "DarkGlass":
                    SetMaterialFloat(material, "_Smoothness", 0.95f);
                    SetMaterialFloat(material, "_Glossiness", 0.95f);
                    material.EnableKeyword("_EMISSION");
                    SetMaterialColor(material, "_EmissionColor", new Color(0.015f, 0.06f, 0.10f));
                    break;
                case "Metal":
                    SetMaterialFloat(material, "_Metallic", 0.75f);
                    SetMaterialFloat(material, "_Smoothness", 0.58f);
                    SetMaterialFloat(material, "_Glossiness", 0.58f);
                    break;
                case "Yellow":
                    SetMaterialFloat(material, "_Smoothness", 0.42f);
                    SetMaterialFloat(material, "_Glossiness", 0.42f);
                    material.EnableKeyword("_EMISSION");
                    SetMaterialColor(material, "_EmissionColor", new Color(0.18f, 0.11f, 0.02f));
                    break;
                case "Blue":
                    SetMaterialFloat(material, "_Smoothness", 0.5f);
                    SetMaterialFloat(material, "_Glossiness", 0.5f);
                    material.EnableKeyword("_EMISSION");
                    SetMaterialColor(material, "_EmissionColor", new Color(0.02f, 0.08f, 0.18f));
                    break;
                case "Concrete":
                case "ConcreteDark":
                case "Sidewalk":
                case "Plaza":
                case "MicroConcrete":
                    SetMaterialFloat(material, "_Smoothness", 0.18f);
                    SetMaterialFloat(material, "_Glossiness", 0.18f);
                    break;
                case "EpoxyFloor":
                    SetMaterialFloat(material, "_Smoothness", 0.46f);
                    SetMaterialFloat(material, "_Glossiness", 0.46f);
                    break;
                case "Asphalt":
                case "Road":
                case "FineAsphalt":
                    SetMaterialFloat(material, "_Smoothness", 0.08f);
                    SetMaterialFloat(material, "_Glossiness", 0.08f);
                    break;
                case "Water":
                    SetMaterialFloat(material, "_Smoothness", 0.78f);
                    SetMaterialFloat(material, "_Glossiness", 0.78f);
                    material.EnableKeyword("_EMISSION");
                    SetMaterialColor(material, "_EmissionColor", new Color(0.02f, 0.12f, 0.18f));
                    break;
                case "NeonCyan":
                    SetMaterialFloat(material, "_Smoothness", 0.72f);
                    SetMaterialFloat(material, "_Glossiness", 0.72f);
                    material.EnableKeyword("_EMISSION");
                    SetMaterialColor(material, "_EmissionColor", new Color(0.00f, 1.15f, 1.45f));
                    break;
                case "NeonPink":
                    SetMaterialFloat(material, "_Smoothness", 0.68f);
                    SetMaterialFloat(material, "_Glossiness", 0.68f);
                    material.EnableKeyword("_EMISSION");
                    SetMaterialColor(material, "_EmissionColor", new Color(1.35f, 0.05f, 0.78f));
                    break;
                case "WarmLight":
                    SetMaterialFloat(material, "_Smoothness", 0.5f);
                    SetMaterialFloat(material, "_Glossiness", 0.5f);
                    material.EnableKeyword("_EMISSION");
                    SetMaterialColor(material, "_EmissionColor", new Color(1.25f, 0.62f, 0.16f));
                    break;
                case "CoolLight":
                    SetMaterialFloat(material, "_Smoothness", 0.54f);
                    SetMaterialFloat(material, "_Glossiness", 0.54f);
                    material.EnableKeyword("_EMISSION");
                    SetMaterialColor(material, "_EmissionColor", new Color(0.28f, 0.72f, 1.25f));
                    break;
            }
        }

        private static void SetMaterialFloat(Material material, string property, float value)
        {
            if (material.HasProperty(property))
            {
                material.SetFloat(property, value);
            }
        }

        private static void SetMaterialColor(Material material, string property, Color value)
        {
            if (material.HasProperty(property))
            {
                material.SetColor(property, value);
            }
        }

        private static Texture2D CreateGeneratedTexture(string pattern)
        {
            var path = MaterialFolder + "/GeneratedTextures/BubuTex_" + pattern + ".asset";
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            const int textureSize = 512;
            if (texture == null)
            {
                texture = new Texture2D(textureSize, textureSize, TextureFormat.RGBA32, true);
                texture.name = "BubuTex_" + pattern;
                texture.wrapMode = TextureWrapMode.Repeat;
                texture.filterMode = FilterMode.Trilinear;
                texture.anisoLevel = 8;
                AssetDatabase.CreateAsset(texture, path);
            }
            else if (texture.width != textureSize || texture.height != textureSize)
            {
                texture.Reinitialize(textureSize, textureSize, TextureFormat.RGBA32, true);
            }

            texture.wrapMode = TextureWrapMode.Repeat;
            texture.filterMode = FilterMode.Trilinear;
            texture.anisoLevel = 8;
            FillGeneratedTexture(texture, pattern);
            EditorUtility.SetDirty(texture);
            return texture;
        }

        private static void FillGeneratedTexture(Texture2D texture, string pattern)
        {
            for (var y = 0; y < texture.height; y++)
            {
                for (var x = 0; x < texture.width; x++)
                {
                    texture.SetPixel(x, y, GeneratedPixel(pattern, x, y));
                }
            }

            texture.Apply(true, false);
        }

        private static Color GeneratedPixel(string pattern, int x, int y)
        {
            switch (pattern)
            {
                case "AsphaltNoise":
                    var noise = ((x * 37 + y * 19 + (x * y) % 23) % 17) / 255f;
                    return new Color(0.055f + noise, 0.058f + noise, 0.062f + noise, 1f);
                case "FineAsphalt":
                    var fineNoise = ((x * 73 + y * 41 + (x * y) % 31) % 23) / 255f;
                    var aggregate = ((x * 11 + y * 17) % 53 == 0) ? 0.045f : 0f;
                    var softTarLine = (x + y * 2) % 97 < 2 ? 0.018f : 0f;
                    return new Color(0.035f + fineNoise + aggregate + softTarLine, 0.037f + fineNoise + aggregate, 0.040f + fineNoise + aggregate, 1f);
                case "SidewalkTiles":
                    if (x % 16 == 0 || y % 16 == 0)
                    {
                        return new Color(0.40f, 0.41f, 0.40f, 1f);
                    }
                    return ((x + y) % 7 == 0) ? new Color(0.62f, 0.63f, 0.61f, 1f) : new Color(0.55f, 0.56f, 0.54f, 1f);
                case "PlazaPavers":
                    if (x % 12 == 0 || y % 12 == 0)
                    {
                        return new Color(0.52f, 0.50f, 0.46f, 1f);
                    }
                    return ((x / 12 + y / 12) % 2 == 0) ? new Color(0.76f, 0.73f, 0.66f, 1f) : new Color(0.66f, 0.64f, 0.58f, 1f);
                case "ConcretePanels":
                    if (x % 24 == 0 || y % 20 == 0)
                    {
                        return new Color(0.43f, 0.44f, 0.43f, 1f);
                    }
                    return ((x * 11 + y * 5) % 13 == 0) ? new Color(0.72f, 0.73f, 0.71f, 1f) : new Color(0.60f, 0.61f, 0.60f, 1f);
                case "MicroConcrete":
                    var pore = ((x * 29 + y * 31 + (x + y) * 7) % 41 == 0) ? -0.055f : 0f;
                    var polish = ((x * 5 + y * 13) % 37) / 720f;
                    if (x % 64 < 2 || y % 64 < 2)
                    {
                        return new Color(0.46f, 0.47f, 0.46f, 1f);
                    }
                    return new Color(0.58f + polish + pore, 0.60f + polish + pore, 0.59f + polish + pore, 1f);
                case "EpoxyGarageFloor":
                    var speckle = ((x * 47 + y * 59 + (x * y) % 43) % 19) / 500f;
                    var parkingGrid = x % 96 < 2 || y % 96 < 2;
                    var safetyFleck = (x * 3 + y * 5) % 149 < 3;
                    if (parkingGrid)
                    {
                        return new Color(0.34f, 0.38f, 0.38f, 1f);
                    }
                    if (safetyFleck)
                    {
                        return new Color(0.55f, 0.50f, 0.30f, 1f);
                    }
                    return new Color(0.25f + speckle, 0.29f + speckle, 0.30f + speckle, 1f);
                case "GlassStripes":
                    if (x % 20 < 2 || y % 18 < 2)
                    {
                        return new Color(0.18f, 0.28f, 0.34f, 0.9f);
                    }
                    if ((x + y) % 29 < 3)
                    {
                        return new Color(0.78f, 0.95f, 1.0f, 0.82f);
                    }
                    return new Color(0.34f, 0.72f, 0.92f, 0.72f);
                case "BrickCourses":
                    if (y % 8 == 0 || x % 18 == 0)
                    {
                        return new Color(0.35f, 0.20f, 0.17f, 1f);
                    }
                    return ((x / 18 + y / 8) % 2 == 0) ? new Color(0.62f, 0.30f, 0.24f, 1f) : new Color(0.50f, 0.24f, 0.20f, 1f);
                default:
                    return Color.white;
            }
        }

        private static void ApplyMaterial(GameObject go, string materialName)
        {
            var renderer = go.GetComponent<Renderer>();
            if (renderer == null) return;
            var material = AssetDatabase.LoadAssetAtPath<Material>(MaterialFolder + "/Bubu_" + materialName + ".mat");
            if (material != null) renderer.sharedMaterial = material;
        }

        private static void RemoveCollider(GameObject go)
        {
            if (go == null)
            {
                return;
            }

            var collider = go.GetComponent<Collider>();
            if (collider != null)
            {
                Object.DestroyImmediate(collider);
            }
        }

        private static void RemoveChildIfExists(Transform parent, string childName)
        {
            var child = parent.Find(childName);
            if (child != null)
            {
                Object.DestroyImmediate(child.gameObject);
            }
        }

        private static void AddSceneToBuildSettings(string scenePath)
        {
            var scenes = new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);
            foreach (var scene in scenes)
            {
                if (scene.path == scenePath)
                {
                    scene.enabled = true;
                    EditorBuildSettings.scenes = scenes.ToArray();
                    return;
                }
            }
            scenes.Add(new EditorBuildSettingsScene(scenePath, true));
            EditorBuildSettings.scenes = scenes.ToArray();
        }

        private static void RequireObject(List<string> errors, string path)
        {
            if (FindSceneObject(path) == null)
            {
                errors.Add("Missing scene object: " + path);
            }
        }

        private static void RequireObjects(List<string> errors, string parentPath, string[] childNames)
        {
            foreach (var childName in childNames)
            {
                RequireObject(errors, parentPath + "/" + childName);
            }
        }

        private static void RequireComponent<T>(List<string> errors, string path) where T : Component
        {
            var go = FindSceneObject(path);
            if (go == null)
            {
                errors.Add("Missing scene object for component check: " + path);
                return;
            }

            if (go.GetComponent<T>() == null)
            {
                errors.Add("Missing component " + typeof(T).Name + " on " + path);
            }
        }

        private static void RequireDaMoguHumanoidLocomotion(List<string> errors)
        {
            var playerPath = "BubuTown_Prototype_All_Visible_Before_Play/08_Player_And_Runtime/Player_Start_Bubu";
            var animatedPath = playerPath + "/DaMogu_VRM_Candidate_Runtime";
            var player = FindSceneObject(playerPath);
            var animated = FindSceneObject(animatedPath);
            if (player == null || animated == null)
            {
                errors.Add("Missing DaMogu VRM Humanoid locomotion scene hookup.");
                return;
            }

            var locomotion = player.GetComponent<BubuTownLocomotionAnimator>();
            var animator = animated.GetComponent<Animator>();
            if (locomotion == null || animator == null)
            {
                errors.Add("DaMogu VRM Humanoid locomotion components are incomplete.");
                return;
            }

            if (locomotion.Animator != animator)
            {
                errors.Add("DaMogu locomotion driver is not linked to the VRM Humanoid Animator.");
            }

            RequireDescendantNamed(errors, animated.transform, "DaMogu_VRM_Candidate_A_AvatarSample_A");

            if (animator.avatar == null || !animator.avatar.isHuman || !animator.avatar.isValid)
            {
                errors.Add("DaMogu VRM Humanoid Animator is missing a valid Humanoid Avatar.");
            }

            var controller = animator.runtimeAnimatorController;
            if (controller == null)
            {
                errors.Add("DaMogu Humanoid Animator is missing a runtime controller.");
                return;
            }

            RequireAnimationClip(errors, controller, "Idle");
            RequireAnimationClip(errors, controller, "WalkForwards");
            RequireAnimationClip(errors, controller, "RunForwards");
            RequireAnimationClip(errors, controller, "SprintForwards");
        }

        private static void RequireAnimationClip(List<string> errors, RuntimeAnimatorController controller, string clipName)
        {
            foreach (var clip in controller.animationClips)
            {
                if (clip != null && clip.name == clipName)
                {
                    return;
                }
            }

            errors.Add("DaMogu Animator Controller is missing clip: " + clipName);
        }

        private static void RequireDescendantNamed(List<string> errors, Transform root, string descendantName)
        {
            if (FindDescendant(root, descendantName) == null)
            {
                errors.Add("Missing DaMogu playable model part: " + descendantName);
            }
        }

        private static Transform FindDescendant(Transform root, string descendantName)
        {
            if (root.name == descendantName)
            {
                return root;
            }

            foreach (Transform child in root)
            {
                var match = FindDescendant(child, descendantName);
                if (match != null)
                {
                    return match;
                }
            }

            return null;
        }

        private static void RequireRouteNodeConnection(List<string> errors, string path, string expectedConnectedNodeId)
        {
            var go = FindSceneObject(path);
            if (go == null)
            {
                errors.Add("Missing scene object for route node connection check: " + path);
                return;
            }

            var node = go.GetComponent<BubuTownUndergroundRouteNode>();
            if (node == null)
            {
                errors.Add("Missing route node component for connection check: " + path);
                return;
            }

            var connections = node.ConnectedNodeIds;
            if (connections != null)
            {
                for (var i = 0; i < connections.Length; i++)
                {
                    if (connections[i] == expectedConnectedNodeId)
                    {
                        return;
                    }
                }
            }

            errors.Add("Route node " + node.NodeId + " is missing connection to " + expectedConnectedNodeId);
        }

        private static void RequireParkingBayData(List<string> errors, string path, string expectedBayId, bool expectedEv, bool expectedVisitor, bool expectedQuestReady)
        {
            var go = FindSceneObject(path);
            if (go == null)
            {
                errors.Add("Missing scene object for parking bay data check: " + path);
                return;
            }

            var bay = go.GetComponent<BubuTownParkingBayMarker>();
            if (bay == null)
            {
                errors.Add("Missing parking bay marker for data check: " + path);
                return;
            }

            if (bay.BayId != expectedBayId)
            {
                errors.Add("Parking bay has wrong id at " + path + ": " + bay.BayId + " expected " + expectedBayId);
            }

            if (bay.ZoneId != "garage_b1")
            {
                errors.Add("Parking bay has wrong zone at " + path + ": " + bay.ZoneId);
            }

            if (bay.IsEvCharging != expectedEv)
            {
                errors.Add("Parking bay " + expectedBayId + " has wrong EV flag.");
            }

            if (bay.IsVisitorReserved != expectedVisitor)
            {
                errors.Add("Parking bay " + expectedBayId + " has wrong visitor flag.");
            }

            if (bay.IsQuestReady != expectedQuestReady)
            {
                errors.Add("Parking bay " + expectedBayId + " has wrong quest-ready flag.");
            }

            if (bay.VehicleSpawnPoint == null)
            {
                errors.Add("Parking bay " + expectedBayId + " is missing vehicle spawn point.");
            }
        }

        private static void RequireNavigationConnection(List<string> errors, string path, string expectedConnectedAnchorId)
        {
            var go = FindSceneObject(path);
            if (go == null)
            {
                errors.Add("Missing scene object for navigation connection check: " + path);
                return;
            }

            var anchor = go.GetComponent<BubuTownNavigationAnchor>();
            if (anchor == null)
            {
                errors.Add("Missing navigation anchor for connection check: " + path);
                return;
            }

            var connections = anchor.ConnectedAnchorIds;
            if (connections != null)
            {
                for (var i = 0; i < connections.Length; i++)
                {
                    if (connections[i] == expectedConnectedAnchorId)
                    {
                        return;
                    }
                }
            }

            errors.Add("Navigation anchor " + anchor.AnchorId + " is missing connection to " + expectedConnectedAnchorId);
        }

        private static void RequireNavigationGraphData(List<string> errors, string path, string requiredAnchorId, int minimumAnchorCount)
        {
            var go = FindSceneObject(path);
            if (go == null)
            {
                errors.Add("Missing scene object for navigation graph data check: " + path);
                return;
            }

            var graph = go.GetComponent<BubuTownNavigationGraph>();
            if (graph == null)
            {
                errors.Add("Missing navigation graph component for data check: " + path);
                return;
            }

            graph.RefreshAnchors();
            if (graph.Anchors == null || graph.Anchors.Length < minimumAnchorCount)
            {
                errors.Add("Navigation graph has too few anchors: " + (graph.Anchors == null ? 0 : graph.Anchors.Length));
            }

            if (graph.FindAnchor(requiredAnchorId) == null)
            {
                errors.Add("Navigation graph cannot find required anchor: " + requiredAnchorId);
            }

            if (graph.ConnectedAnchors(requiredAnchorId).Length == 0)
            {
                errors.Add("Navigation graph required anchor has no connected anchors: " + requiredAnchorId);
            }
        }

        private static void RequireNavigationDebugRoute(List<string> errors, string path, int minimumRouteLength)
        {
            var go = FindSceneObject(path);
            if (go == null)
            {
                errors.Add("Missing scene object for navigation debug route check: " + path);
                return;
            }

            var routeDebugger = go.GetComponent<BubuTownNavigationRouteDebugger>();
            if (routeDebugger == null)
            {
                errors.Add("Missing navigation route debugger component for route check: " + path);
                return;
            }

            routeDebugger.RefreshRoute();
            if (!routeDebugger.HasValidRoute())
            {
                errors.Add("Navigation debug route cannot build route: " + path);
                return;
            }

            if (routeDebugger.LastRoute.Length < minimumRouteLength)
            {
                errors.Add("Navigation debug route is too short at " + path + ": " + routeDebugger.LastRoute.Length + " expected at least " + minimumRouteLength);
            }
        }

        private static void RequireAsset(List<string> errors, string path)
        {
            if (AssetDatabase.LoadAssetAtPath<Object>(path) == null)
            {
                errors.Add("Missing asset: " + path);
            }
        }

        private static void RequireGeneratedTextureQuality(List<string> errors, string pattern)
        {
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(MaterialFolder + "/GeneratedTextures/BubuTex_" + pattern + ".asset");
            if (texture == null)
            {
                errors.Add("Missing generated texture quality target: " + pattern);
                return;
            }

            if (texture.width < 512 || texture.height < 512)
            {
                errors.Add("Generated texture is too small: " + pattern + " " + texture.width + "x" + texture.height);
            }

            if (texture.filterMode == FilterMode.Point)
            {
                errors.Add("Generated texture still uses Point filtering: " + pattern);
            }

            if (texture.anisoLevel < 8)
            {
                errors.Add("Generated texture anisotropic filtering is too low: " + pattern);
            }
        }

        private static void RequireMainCameraQuality(List<string> errors)
        {
            var cameraObject = FindSceneObject("BubuTown_Prototype_All_Visible_Before_Play/00_Lighting_And_Camera/Main Camera");
            var camera = cameraObject != null ? cameraObject.GetComponent<Camera>() : null;
            if (camera == null)
            {
                errors.Add("Missing main camera for quality audit.");
                return;
            }

            if (!camera.allowHDR)
            {
                errors.Add("Main camera HDR is disabled.");
            }

            if (!camera.allowMSAA)
            {
                errors.Add("Main camera MSAA is disabled.");
            }

            if (QualitySettings.antiAliasing < 4)
            {
                errors.Add("QualitySettings antiAliasing is below 4x.");
            }

            if (QualitySettings.anisotropicFiltering == AnisotropicFiltering.Disable)
            {
                errors.Add("Anisotropic filtering is disabled.");
            }
        }

        private static void ValidateNoBrokenRendererMaterials(List<string> errors)
        {
            var renderers = Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None);
            var brokenCount = 0;
            foreach (var renderer in renderers)
            {
                if (renderer == null || string.IsNullOrEmpty(renderer.gameObject.scene.path))
                {
                    continue;
                }

                foreach (var material in renderer.sharedMaterials)
                {
                    if (material == null)
                    {
                        brokenCount++;
                        if (brokenCount <= 12)
                        {
                            errors.Add("Renderer has missing material: " + GetScenePath(renderer.transform));
                        }
                        continue;
                    }

                    if (material.shader == null || material.shader.name.Contains("Hidden/InternalErrorShader"))
                    {
                        brokenCount++;
                        if (brokenCount <= 12)
                        {
                            var shaderName = material.shader == null ? "null" : material.shader.name;
                            errors.Add("Renderer uses broken shader: " + GetScenePath(renderer.transform) + " material=" + material.name + " shader=" + shaderName);
                        }
                    }
                }
            }

            if (brokenCount > 12)
            {
                errors.Add("Additional broken renderer materials omitted: " + (brokenCount - 12));
            }
        }

        private static void ValidateSceneTextureFiltering(List<string> errors)
        {
            var renderers = Object.FindObjectsByType<Renderer>(FindObjectsInactive.Include, FindObjectsSortMode.None);
            var pointCount = 0;
            foreach (var renderer in renderers)
            {
                if (renderer == null || string.IsNullOrEmpty(renderer.gameObject.scene.path))
                {
                    continue;
                }

                foreach (var material in renderer.sharedMaterials)
                {
                    if (material == null)
                    {
                        continue;
                    }

                    var texture = material.mainTexture as Texture2D;
                    if (texture == null)
                    {
                        continue;
                    }

                    if (texture.filterMode == FilterMode.Point)
                    {
                        pointCount++;
                        if (pointCount <= 12)
                        {
                            errors.Add("Scene texture uses Point filtering: " + texture.name + " on " + GetScenePath(renderer.transform));
                        }
                    }
                }
            }

            if (pointCount > 12)
            {
                errors.Add("Additional point-filtered scene textures omitted: " + (pointCount - 12));
            }
        }

        private static string GetScenePath(Transform transform)
        {
            var names = new List<string>();
            var current = transform;
            while (current != null)
            {
                names.Add(current.name);
                current = current.parent;
            }

            names.Reverse();
            return string.Join("/", names);
        }

        private static GameObject FindSceneObject(string path)
        {
            var parts = path.Split('/');
            if (parts.Length == 0)
            {
                return null;
            }

            foreach (var root in SceneManager.GetActiveScene().GetRootGameObjects())
            {
                if (root.name != parts[0])
                {
                    continue;
                }

                var current = root.transform;
                for (var i = 1; i < parts.Length; i++)
                {
                    current = current.Find(parts[i]);
                    if (current == null)
                    {
                        return null;
                    }
                }

                return current.gameObject;
            }

            return null;
        }
    }
}
